"""Error-tolerant parsing of Python source into an AST.

Syntax errors are repaired line by line: the offending line is replaced by a
sequence of progressively more conservative candidates (a placeholder name at
the cursor, `pass`, and finally a blank line) until the module parses.  Lines
are never inserted or removed, so AST line numbers match the original file.
"""
import ast
import re
import time
import warnings

# Identifier inserted at the cursor to make incomplete expressions parseable.
# Bindings whose names contain it are ignored by scope analysis.
PLACEHOLDER = "__sith_cursor__"

# After this many seconds of repairs, everything from the error onward is dropped.
_TIME_BUDGET = 1.0
_INDENTATION_ERRORS = ("unindent does not match", "unexpected indent")
_INDENTED_BLOCK = re.compile(r"expected an indented block after .* on line (\d+)")

_CLOSERS = {"(": ")", "[": "]", "{": "}"}
# Keywords that can never appear inside a bracketed expression.
_STATEMENT_KEYWORDS = {
    "def", "class", "return", "import", "pass", "break", "continue", "raise", "del",
    "global", "nonlocal", "assert", "while", "with", "try", "except", "finally", "elif",
}
# Keywords that, at or below the opening line's indentation, start a new statement.
_BLOCK_KEYWORDS = {"if", "for", "else", "async", "from", "match", "case"}
_FIRST_WORD = re.compile(r"[A-Za-z_]\w*")


def parse_tolerant(text, cursor=None):
    """Parse `text`, repairing syntax errors. `cursor` is (line, col) or None."""
    lines = close_brackets(text.replace("\0", " ").split("\n"))
    return _Repairer(lines, cursor).run()


def close_brackets(lines):
    """Close brackets left open when a new statement evidently begins.

    An unclosed bracket otherwise swallows every following line, and the
    parser then blames those (valid) lines instead of the incomplete one.
    """
    lines = list(lines)
    stack = []  # (bracket, line index)
    triple = None
    for index, line in enumerate(lines):
        if stack and triple is None and _starts_statement(line, lines[stack[0][1]]):
            _append_closers(lines, stack, index)
        triple = _scan_brackets(line, stack, triple, index)
    if stack and triple is None:
        _append_closers(lines, stack, len(lines))
    return lines


def _starts_statement(line, opener_line):
    code = line.strip()
    if not code or code.startswith("#"):
        return False
    indent = len(_indent_of(line))
    opener_indent = len(_indent_of(opener_line))
    match = _FIRST_WORD.match(code)
    word = match.group(0) if match else ""
    if word in _STATEMENT_KEYWORDS:
        return True
    if indent <= opener_indent and (word in _BLOCK_KEYWORDS or code.startswith("@")):
        return True
    return indent < opener_indent and code[0] not in ")]}"


def _append_closers(lines, stack, before):
    """Append closers for `stack` to the last code line before index `before`."""
    for index in range(before - 1, stack[0][1] - 1, -1):
        code = strip_comment(lines[index]).rstrip()
        if code.strip():
            lines[index] = code + "".join(_CLOSERS[b] for b, _ in reversed(stack))
            break
    stack.clear()


def _scan_brackets(line, stack, triple, index):
    """Update the bracket stack with `line`; returns the open triple quote, if any."""
    i = 0
    while i < len(line):
        if triple is not None:
            end = line.find(triple, i)
            if end < 0:
                return triple
            i = end + 3
            triple = None
            continue
        char = line[i]
        if char == "#":
            break
        if char in "\"'":
            if line.startswith(char * 3, i):
                triple = char * 3
                i += 3
                continue
            i += 1
            while i < len(line) and line[i] != char:
                i += 2 if line[i] == "\\" else 1
        elif char in _CLOSERS:
            stack.append((char, index))
        elif char in ")]}" and stack and _CLOSERS[stack[-1][0]] == char:
            stack.pop()
        i += 1
    return triple


def strip_comment(line):
    """Remove a trailing `#` comment, ignoring `#` inside string literals."""
    quote = None
    i = 0
    while i < len(line):
        char = line[i]
        if quote:
            if char == "\\":
                i += 1
            elif char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == "#":
            return line[:i]
        i += 1
    return line


def _neighbour_indent(lines):
    """Indentation of the first code line in `lines`, or None."""
    for line in lines:
        if line.strip() and not line.strip().startswith("#"):
            return len(_indent_of(line))
    return None


def _indent_of(line):
    return line[: len(line) - len(line.lstrip())]


class _Repairer:
    def __init__(self, lines, cursor):
        self.original = lines
        self.state = list(lines)
        self.cursor = cursor
        self.candidates = {}
        self.positions = {}
        self.pass_appended = set()
        self.string_closed = False
        self.truncated = False
        self.deadline = None

    def run(self):
        limit = 4 * len(self.state) + 20
        self.deadline = time.monotonic() + _TIME_BUDGET
        with warnings.catch_warnings():
            warnings.simplefilter("ignore")
            for _ in range(limit):
                try:
                    return ast.parse("\n".join(self.state))
                except (SyntaxError, ValueError) as error:
                    if not self._repair(error):
                        break
        return ast.Module(body=[], type_ignores=[])

    def _repair(self, error):
        count = len(self.state)
        line = getattr(error, "lineno", None) or count
        line = max(1, min(line, count))
        message = str(getattr(error, "msg", ""))
        if "unterminated triple-quoted string" in message and self._close_string(error, line):
            return True
        if not self.truncated and time.monotonic() > self.deadline:
            self._drop_from(line)
            return True
        match = _INDENTED_BLOCK.search(message)
        if match:
            if self._is_cursor_line(line) and self._advance(line):
                return True
            if self._append_pass(int(match.group(1)), line):
                return True
        if any(text in message for text in _INDENTATION_ERRORS) and self._blank(line):
            return True
        if self._advance(line):
            return True
        for previous in range(line - 1, 0, -1):
            if self._advance(previous):
                return True
        return False

    def _is_cursor_line(self, line):
        return self.cursor is not None and self.cursor[0] == line

    def _drop_from(self, line):
        """Give up on the rest of the file: blank every line from `line` on."""
        for index in range(line - 1, len(self.state)):
            self.state[index] = ""
            self._line_candidates(index + 1)
            self.positions[index + 1] = len(self.candidates[index + 1]) - 1
        self.truncated = True

    def _blank(self, line):
        """Jump straight to the blank candidate (indentation cannot be fixed in place)."""
        options = self._line_candidates(line)
        if self.state[line - 1] == "":
            return False
        self.positions[line] = len(options) - 1
        self.state[line - 1] = ""
        return True

    def _close_string(self, error, line):
        """Terminate a triple-quoted string that runs to the end of the file."""
        offset = (getattr(error, "offset", None) or 1) - 1
        quote = self.state[line - 1][offset:offset + 3]
        if quote not in ('"""', "'''") or self.string_closed:
            return False
        self.state[-1] += " " + quote
        self.string_closed = True
        return True

    def _append_pass(self, header_line, error_line):
        """Give a block header with a missing body an inline `pass` body."""
        last = min(max(error_line, header_line), len(self.state))
        for line in range(last, header_line - 1, -1):
            code = strip_comment(self.state[line - 1]).rstrip()
            if code.endswith(":") and line not in self.pass_appended:
                self.state[line - 1] = code + " pass"
                self.pass_appended.add(line)
                return True
        return False

    def _line_candidates(self, line):
        if line not in self.candidates:
            text = self.original[line - 1]
            indent = _indent_of(text)
            options = [text]
            if self._is_cursor_line(line):
                col = min(self.cursor[1], len(text))
                options.append(text[:col] + PLACEHOLDER + text[col:])
                options.append(text[:col] + PLACEHOLDER)
            if self._out_of_place(line, text):
                options.append("")
            header = self._header_replacement(line, text)
            if header:
                options.append(header)
            options += [indent + "pass", ""]
            unique = []
            for option in options:
                if option not in unique:
                    unique.append(option)
            self.candidates[line] = unique
            self.positions[line] = 0
        return self.candidates[line]

    def _out_of_place(self, line, text):
        """True for a line dedented below both its neighbouring code lines."""
        indent = len(_indent_of(text))
        before = _neighbour_indent(reversed(self.original[: line - 1]))
        after = _neighbour_indent(self.original[line:])
        return before is not None and after is not None and indent < min(before, after)

    def _header_replacement(self, line, text):
        """A valid block header for a broken line that is followed by a block.

        Keeping a header lets the indented body that follows still parse,
        instead of failing line by line with "unexpected indent".
        """
        indent = _indent_of(text)
        for following in self.original[line:]:
            if following.strip() and not following.strip().startswith("#"):
                if len(_indent_of(following)) <= len(indent):
                    return None
                break
        else:
            return None
        word = (_FIRST_WORD.match(text.strip()) or [""])[0]
        if word in ("def", "async"):
            return f"{indent}def {PLACEHOLDER}():"
        if word == "class":
            return f"{indent}class {PLACEHOLDER}:"
        return f"{indent}if True:"

    def _advance(self, line):
        """Switch `line` to its next repair candidate; False when exhausted."""
        options = self._line_candidates(line)
        position = self.positions[line]
        while position + 1 < len(options):
            position += 1
            if options[position] != self.state[line - 1]:
                self.positions[line] = position
                self.state[line - 1] = options[position]
                return True
        self.positions[line] = position
        return False
"""Inferred values: what an expression evaluates to, statically."""
import inspect

MODULE = "module"
CLASS = "class"
FUNCTION = "function"
INSTANCE = "instance"


class Value:
    kind = None

    @property
    def type_name(self):
        return None

    @property
    def key(self):
        """Identity used to de-duplicate unions of inferred values."""
        return (type(self).__name__, id(self._identity()))

    def _identity(self):
        return self


class LocalModule(Value):
    """A module parsed from a project source file."""

    kind = MODULE

    def __init__(self, context):
        self.context = context

    def _identity(self):
        return self.context


class RuntimeModule(Value):
    """An installed module, imported for introspection."""

    kind = MODULE

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class LocalClass(Value):
    """A class defined by a `class` statement in parsed source."""

    kind = CLASS

    def __init__(self, scope):
        self.scope = scope

    def _identity(self):
        return self.scope

    @property
    def node(self):
        return self.scope.node

    @property
    def name(self):
        return self.scope.node.name


class LocalFunction(Value):
    """A `def` or `lambda` from parsed source, optionally bound to `self`/`cls`."""

    kind = FUNCTION

    def __init__(self, scope, bound=None):
        self.scope = scope
        self.bound = bound

    def _identity(self):
        return self.scope

    @property
    def node(self):
        return self.scope.node


class LocalInstance(Value):
    """An instance of a local class; `init_args` maps `__init__` parameters to values."""

    kind = INSTANCE

    def __init__(self, cls, init_args=None):
        self.cls = cls
        self.init_args = init_args

    def _identity(self):
        return self.cls.scope

    @property
    def type_name(self):
        return self.cls.name


class RuntimeClass(Value):
    kind = CLASS

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class RuntimeFunction(Value):
    kind = FUNCTION

    def __init__(self, obj):
        self.obj = obj

    def _identity(self):
        return self.obj


class RuntimeInstance(Value):
    """An instance of a runtime class (also used for literals)."""

    kind = INSTANCE

    def __init__(self, cls):
        self.cls = cls

    def _identity(self):
        return self.cls

    @property
    def type_name(self):
        return self.cls.__name__


def unique(values):
    """`values` without duplicates (by identity key), in order."""
    seen = set()
    result = []
    for value in values:
        if value is not None and value.key not in seen:
            seen.add(value.key)
            result.append(value)
    return result


def wrap_runtime(obj):
    """Wrap a live Python object as a Value (None for opaque data descriptors)."""
    if inspect.ismodule(obj):
        return RuntimeModule(obj)
    if inspect.isclass(obj):
        return RuntimeClass(obj)
    origin = getattr(obj, "__origin__", None)
    if inspect.isclass(origin):  # generic aliases such as typing.List or list[int]
        return RuntimeClass(origin)
    if callable(obj):
        return RuntimeFunction(obj)
    if inspect.isdatadescriptor(obj):
        return None
    return RuntimeInstance(type(obj))


# Builtin types whose attributes are introspected on a real (empty) instance,
# so that e.g. `(1).real` is known to be an int rather than a descriptor.
_SAMPLE_TYPES = (bool, int, float, complex, str, bytes, bytearray, list, tuple, dict, set,
                 frozenset, type(None))


def runtime_sample(cls):
    """An instance of `cls` to introspect, or the class itself."""
    if cls in _SAMPLE_TYPES:
        return cls()
    return cls
"""Scope analysis: which names each scope binds, and where."""
import ast
from dataclasses import dataclass, field

from .parsing import PLACEHOLDER

MODULE = "module"
FUNCTION = "function"
CLASS = "class"
LAMBDA = "lambda"
COMPREHENSION = "comprehension"

_FUNCTION_NODES = (ast.FunctionDef, ast.AsyncFunctionDef)
_COMPREHENSION_NODES = (ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp)


@dataclass(eq=False)
class Binding:
    """A single place where a name is bound."""

    name: str
    line: int
    kind: str
    node: ast.AST
    scope: "Scope"
    value: ast.AST = None
    extra: dict = field(default_factory=dict)
    # The node naming the bound identifier (ast.Name, ast.arg, ast.alias, ...).
    target: ast.AST = None


@dataclass(eq=False)
class StarImport:
    """A `from module import *` statement."""

    module: str
    level: int
    line: int
    scope: "Scope"
    node: ast.AST = None


class Scope:
    """A namespace: module, function, class, lambda or comprehension."""

    def __init__(self, kind, node, parent, module):
        self.kind = kind
        self.node = node
        self.parent = parent
        self.module = module
        self.bindings = {}
        self.star_imports = []
        self.children = []
        self.global_names = set()
        self.local_node_ids = None  # ids of the nodes of the body, cached by flow analysis
        self.nonlocal_names = set()
        if parent is not None:
            parent.children.append(self)

    def add(self, binding):
        self.bindings.setdefault(binding.name, []).append(binding)

    def chain(self):
        """This scope followed by all its ancestors."""
        scope = self
        while scope is not None:
            yield scope
            scope = scope.parent

    def root(self):
        scope = self
        while scope.parent is not None:
            scope = scope.parent
        return scope


def iter_target_names(target, value):
    """Yield (Name node, value expression or None) pairs for an assignment target."""
    if isinstance(target, ast.Name):
        yield target, value
    elif isinstance(target, (ast.Tuple, ast.List)):
        values = None
        if (
            isinstance(value, (ast.Tuple, ast.List))
            and len(value.elts) == len(target.elts)
            and not any(isinstance(e, ast.Starred) for e in target.elts + value.elts)
        ):
            values = value.elts
        for index, element in enumerate(target.elts):
            yield from iter_target_names(element, values[index] if values else None)
    elif isinstance(target, ast.Starred):
        yield from iter_target_names(target.value, None)


def function_parameters(arguments):
    """All parameter `arg` nodes of an `ast.arguments`, in declaration order."""
    params = list(arguments.posonlyargs) + list(arguments.args)
    if arguments.vararg:
        params.append(arguments.vararg)
    params += list(arguments.kwonlyargs)
    if arguments.kwarg:
        params.append(arguments.kwarg)
    return params


def walk_local(statements):
    """Walk nodes of a body without descending into nested scopes."""
    stack = list(reversed(statements))
    while stack:
        node = stack.pop()
        yield node
        if isinstance(node, _FUNCTION_NODES + (ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(reversed(list(ast.iter_child_nodes(node))))


def _declared(statements, kind):
    """Names declared `global`/`nonlocal` directly in a function body."""
    names = set()
    stack = list(statements)
    while stack:
        node = stack.pop()
        if isinstance(node, kind):
            names.update(node.names)
        if isinstance(node, _FUNCTION_NODES + (ast.ClassDef, ast.Lambda)):
            continue
        stack.extend(ast.iter_child_nodes(node))
    return names


class ScopeBuilder:
    """Walks a module AST and builds its tree of scopes."""

    def __init__(self, module_context):
        self.module_context = module_context
        self.scope_by_node = {}
        self.binding_by_target = {}

    def build(self, tree):
        root = self._new_scope(MODULE, tree, None)
        self._statements(root, tree.body)
        return root

    def _new_scope(self, kind, node, parent):
        scope = Scope(kind, node, parent, self.module_context)
        self.scope_by_node[id(node)] = scope
        return scope

    # -- binding helpers -------------------------------------------------

    def _bind(self, scope, name, line, kind, node, value=None, target=None, **extra):
        if PLACEHOLDER in name:
            return
        if scope.kind == FUNCTION:
            if name in scope.nonlocal_names:
                return
            if name in scope.global_names:
                scope = scope.root()
        binding = Binding(name, line, kind, node, scope, value, extra, target)
        scope.add(binding)
        self.binding_by_target.setdefault(id(target if target is not None else node), binding)

    def _bind_target(self, scope, target, kind, value, node, **extra):
        for name_node, element_value in iter_target_names(target, value):
            self._bind(scope, name_node.id, name_node.lineno, kind, node, element_value,
                       target=name_node, **extra)
        for child in ast.walk(target):
            if isinstance(child, (ast.Attribute, ast.Subscript)):
                self._expression(scope, child)

    def _bind_arguments(self, scope, function_node):
        for index, param in enumerate(function_parameters(function_node.args)):
            self._bind(scope, param.arg, function_node.lineno, "param", function_node,
                       target=param, arg=param, index=index)

    # -- statements --------------------------------------------------------

    def _statements(self, scope, statements):
        for statement in statements:
            self._statement(scope, statement)

    def _statement(self, scope, node):
        handler = getattr(self, "_stmt_" + type(node).__name__, None)
        if handler is not None:
            handler(scope, node)
            return
        for child in ast.iter_child_nodes(node):
            if isinstance(child, ast.stmt):
                self._statement(scope, child)
            else:
                self._expression(scope, child)

    def _stmt_FunctionDef(self, scope, node):
        for expression in node.decorator_list + node.args.defaults + node.args.kw_defaults:
            self._expression(scope, expression)
        for param in function_parameters(node.args):
            self._expression(scope, param.annotation)
        self._expression(scope, node.returns)
        self._bind(scope, node.name, node.lineno, "def", node)
        child = self._new_scope(FUNCTION, node, scope)
        child.global_names = _declared(node.body, ast.Global)
        child.nonlocal_names = _declared(node.body, ast.Nonlocal)
        self._bind_arguments(child, node)
        self._statements(child, node.body)

    _stmt_AsyncFunctionDef = _stmt_FunctionDef

    def _stmt_ClassDef(self, scope, node):
        for expression in node.decorator_list + node.bases + [k.value for k in node.keywords]:
            self._expression(scope, expression)
        self._bind(scope, node.name, node.lineno, "class", node)
        child = self._new_scope(CLASS, node, scope)
        self._statements(child, node.body)

    def _stmt_Assign(self, scope, node):
        self._expression(scope, node.value)
        for target in node.targets:
            self._bind_target(scope, target, "assign", node.value, node)

    def _stmt_AnnAssign(self, scope, node):
        self._expression(scope, node.value)
        self._expression(scope, node.annotation)
        if isinstance(node.target, ast.Name):
            self._bind(scope, node.target.id, node.target.lineno, "assign", node, node.value,
                       target=node.target, annotation=node.annotation)
        else:
            self._expression(scope, node.target)

    def _stmt_AugAssign(self, scope, node):
        self._expression(scope, node.value)
        target = node.target
        if isinstance(target, ast.Name):
            if target.id not in scope.bindings:
                self._bind(scope, target.id, target.lineno, "augassign", node, target=target)
        else:
            self._expression(scope, target)

    def _stmt_For(self, scope, node):
        self._expression(scope, node.iter)
        self._bind_target(scope, node.target, "loop", None, node)
        self._statements(scope, node.body)
        self._statements(scope, node.orelse)

    _stmt_AsyncFor = _stmt_For

    def _stmt_With(self, scope, node):
        for item in node.items:
            self._expression(scope, item.context_expr)
            if item.optional_vars is not None:
                self._bind_target(scope, item.optional_vars, "with", None, node,
                                  context=item.context_expr)
        self._statements(scope, node.body)

    _stmt_AsyncWith = _stmt_With

    def _stmt_Try(self, scope, node):
        self._statements(scope, node.body)
        for handler in node.handlers:
            self._expression(scope, handler.type)
            if handler.name:
                self._bind(scope, handler.name, handler.lineno, "except", handler,
                           exception=handler.type)
            self._statements(scope, handler.body)
        self._statements(scope, node.orelse)
        self._statements(scope, node.finalbody)

    _stmt_TryStar = _stmt_Try

    def _stmt_Match(self, scope, node):
        self._expression(scope, node.subject)
        for case in node.cases:
            for pattern in ast.walk(case.pattern):
                for attribute in ("name", "rest"):
                    name = getattr(pattern, attribute, None)
                    if isinstance(name, str):
                        self._bind(scope, name, pattern.lineno, "pattern", case, target=pattern)
                if isinstance(pattern, ast.MatchValue):
                    self._expression(scope, pattern.value)
            self._expression(scope, case.guard)
            self._statements(scope, case.body)

    def _stmt_Import(self, scope, node):
        for alias in node.names:
            if alias.asname:
                self._bind(scope, alias.asname, node.lineno, "import", node, target=alias,
                           module=alias.name)
            else:
                top = alias.name.split(".")[0]
                self._bind(scope, top, node.lineno, "import", node, target=alias, module=top)

    def _stmt_ImportFrom(self, scope, node):
        for alias in node.names:
            if alias.name == "*":
                scope.star_imports.append(
                    StarImport(node.module or "", node.level, node.lineno, scope, node))
            else:
                self._bind(scope, alias.asname or alias.name, node.lineno, "importfrom", node,
                           target=alias, module=node.module or "", level=node.level,
                           attribute=alias.name)

    def _stmt_Global(self, scope, node):
        pass

    _stmt_Nonlocal = _stmt_Global

    # -- expressions -------------------------------------------------------

    def _expression(self, scope, node):
        if node is None or not isinstance(node, ast.AST):
            return
        if isinstance(node, ast.Lambda):
            for default in node.args.defaults + node.args.kw_defaults:
                self._expression(scope, default)
            child = self._new_scope(LAMBDA, node, scope)
            self._bind_arguments(child, node)
            self._expression(child, node.body)
        elif isinstance(node, _COMPREHENSION_NODES):
            child = self._new_scope(COMPREHENSION, node, scope)
            for index, generator in enumerate(node.generators):
                self._expression(scope if index == 0 else child, generator.iter)
                self._bind_target(child, generator.target, "comprehension", None, generator)
                for condition in generator.ifs:
                    self._expression(child, condition)
            if isinstance(node, ast.DictComp):
                self._expression(child, node.key)
                self._expression(child, node.value)
            else:
                self._expression(child, node.elt)
        elif isinstance(node, ast.NamedExpr):
            self._expression(scope, node.value)
            target_scope = scope
            while target_scope.kind == COMPREHENSION:
                target_scope = target_scope.parent
            self._bind(target_scope, node.target.id, node.target.lineno, "assign", node, node.value,
                       target=node.target)
        else:
            for child in ast.iter_child_nodes(node):
                self._expression(scope, child)

"""Textual analysis of the cursor position: prefix and completion kind."""
import re
from dataclasses import dataclass

NAME = "name"
ATTRIBUTE = "attribute"
NONE = "none"

_OPENERS = {")": "(", "]": "[", "}": "{"}
_STRING_PREFIX_CHARS = "rRbBuUfF"


@dataclass
class CursorContext:
    """What kind of completion is requested and what has been typed so far."""

    kind: str
    prefix: str = ""
    receiver: str = ""


def is_identifier_char(char):
    return char == "_" or char.isalnum()


def analyze(text_before_cursor):
    """Classify the completion request from the source text before the cursor."""
    end = len(text_before_cursor)
    start = end
    while start > 0 and is_identifier_char(text_before_cursor[start - 1]):
        start -= 1
    prefix = text_before_cursor[start:]
    if prefix and prefix[0].isdigit():
        return CursorContext(NONE, prefix)

    before = text_before_cursor[:start]
    if not before.endswith("."):
        return CursorContext(NAME, prefix)

    receiver = extract_receiver(before[:-1])
    if not receiver or receiver.isdigit() or receiver.endswith("."):
        return CursorContext(NONE, prefix)
    return CursorContext(ATTRIBUTE, prefix, receiver)


def extract_receiver(text):
    """Return the expression text that ends at the end of `text`, or None."""
    i = len(text)
    while i > 0:
        char = text[i - 1]
        if char in _OPENERS:
            opener = _match_open(text, i - 1)
            if opener is None:
                return None
            i = opener
            continue
        if is_identifier_char(char):
            while i > 0 and is_identifier_char(text[i - 1]):
                i -= 1
            if i > 0 and text[i - 1] == ".":
                i -= 1
                continue
            break
        if char in "\"'":
            start = _string_start(text, i - 1)
            if start is None:
                return None
            i = start
            while i > 0 and text[i - 1] in _STRING_PREFIX_CHARS:
                i -= 1
            break
        break
    return text[i:].strip()


def _match_open(text, close_index):
    """Index of the bracket opening the one at `close_index`, scanning backwards."""
    stack = [text[close_index]]
    i = close_index - 1
    while i >= 0:
        char = text[i]
        if char in "\"'":
            start = _string_start(text, i)
            if start is None:
                return None
            i = start - 1
            continue
        if char in _OPENERS:
            stack.append(char)
        elif char in "([{":
            if _OPENERS[stack[-1]] != char:
                return None
            stack.pop()
            if not stack:
                return i
        i -= 1
    return None


def _string_start(text, end_index):
    """Index of the opening quote of the string literal ending at `end_index`."""
    quote = text[end_index]
    if end_index >= 2 and text[end_index - 2:end_index + 1] == quote * 3:
        start = text.rfind(quote * 3, 0, end_index - 2)
        return None if start < 0 else start
    i = end_index - 1
    while i >= 0:
        if text[i] == quote and (i == 0 or text[i - 1] != "\\"):
            return i
        if text[i] == "\n":
            return None
        i -= 1
    return None


# -- import statements --------------------------------------------------------------

IMPORT_MODULE = "import-module"
IMPORT_NAME = "import-name"
IMPORT_KEYWORD = "import-keyword"
IMPORT_NOTHING = "import-nothing"

_STATEMENT_START = re.compile(r"\s*(?:from|import)\b")
_DOTTED = r"((?:\w+\s*\.\s*)*)(\w*)"
_IMPORT = re.compile(r"\s*import\s+(.*)", re.S)
_FROM = re.compile(r"\s*from\s+(.*)", re.S)
_FROM_NAMES = re.compile(r"(\.*)\s*([\w.\s]*?)\s*\bimport\s+(.*)", re.S)
_FROM_KEYWORD = re.compile(r"(\.*)\s*(\w+(?:\s*\.\s*\w+)*|)\s+(\w*)", re.S)
_FROM_MODULE = re.compile(r"(\.*)\s*" + _DOTTED, re.S)
_ITEM = re.compile(_DOTTED, re.S)
_NAME = re.compile(r"(\w*)")


@dataclass
class ImportContext:
    """A cursor inside an import statement.

    `module` is the dotted module (relative to `level` leading dots) whose
    submodules or names are completed; `prefix` is what has been typed.
    """

    kind: str
    prefix: str = ""
    module: str = ""
    level: int = 0


def analyze_import(text_before_cursor):
    """An ImportContext when the cursor is inside an import statement, else None."""
    statement = _import_statement(text_before_cursor)
    if statement is None:
        return None
    if re.fullmatch(r"\s*(?:import|from)", statement):
        return None  # still typing the keyword itself
    match = _IMPORT.fullmatch(statement)
    if match:
        item = match.group(1).split(",")[-1].lstrip()
        found = _ITEM.fullmatch(item)
        if not found:
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_MODULE, found.group(2), _dotted(found.group(1)))
    match = _FROM.fullmatch(statement)
    if not match:
        return ImportContext(IMPORT_NOTHING)
    rest = match.group(1)
    found = _FROM_NAMES.fullmatch(rest)
    if found and (found.group(1) or found.group(2).strip()):
        module = re.sub(r"\s+", "", found.group(2))
        item = found.group(3).split(",")[-1].strip()
        name = _NAME.fullmatch(item)
        if not name or not (module.replace(".", "").isidentifier() or not module):
            return ImportContext(IMPORT_NOTHING)
        return ImportContext(IMPORT_NAME, name.group(1), module, len(found.group(1)))
    found = _FROM_KEYWORD.fullmatch(rest)
    if found and (found.group(1) or found.group(2)):
        return ImportContext(IMPORT_KEYWORD, found.group(3))
    found = _FROM_MODULE.fullmatch(rest)
    if found:
        return ImportContext(IMPORT_MODULE, found.group(3), _dotted(found.group(2)),
                             len(found.group(1)))
    return ImportContext(IMPORT_NOTHING)


def _dotted(text):
    """`a . b .` -> `a.b`."""
    return ".".join(part for part in re.sub(r"\s+", "", text).split(".") if part)


def _import_statement(text):
    """The text of the import statement the cursor is in, joined onto one line, or None."""
    lines = text.split("\n")
    current = len(lines) - 1
    lines[current] = _last_simple_statement(lines[current])
    for start in range(current, max(-1, current - 100), -1):
        if _STATEMENT_START.match(lines[start]):
            if not _continues(lines[start:current]):
                return None
            joined = " ".join(_code(line).rstrip().rstrip("\\") for line in lines[start:current])
            joined = (joined + " " + lines[current]) if start < current else lines[current]
            return joined.replace("(", " ").replace(")", " ")
    return None


def _code(line):
    """`line` without a trailing comment."""
    quote = None
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char == "#":
            return line[:index]
    return line


def _last_simple_statement(line):
    """The part of `line` after its last top-level `;`."""
    depth = 0
    quote = None
    start = 0
    for index, char in enumerate(line):
        if quote:
            if char == quote:
                quote = None
        elif char in "\"'":
            quote = char
        elif char in "([{":
            depth += 1
        elif char in ")]}":
            depth -= 1
        elif char == ";" and depth <= 0:
            start = index + 1
    return line[start:]


def _continues(lines):
    """True when each of `lines` continues onto the next (open bracket or backslash)."""
    depth = 0
    for line in lines:
        code = _code(line)
        depth += code.count("(") - code.count(")")
        if depth <= 0 and not code.rstrip().endswith("\\"):
            return False
    return True
"""Module contexts and import resolution (project files first, then the standard library)."""
import ast
import contextlib
import importlib
import importlib.util
import io
import os
import pkgutil
import sys
import warnings

from .parsing import parse_tolerant
from .scopes import ScopeBuilder
from .source import read_text
from .errors import SithError
from .values import LocalModule, RuntimeModule

STDLIB_NAMES = frozenset(sys.stdlib_module_names) | frozenset(sys.builtin_module_names)


class ModuleContext:
    """A parsed Python module together with its scope tree.

    A namespace package (a directory without `__init__.py`) is a context
    without a path and with an empty syntax tree.
    """

    def __init__(self, path, name, tree, text="", directory=None):
        self.path = os.path.abspath(path) if path else None
        if directory is not None:
            self.directory = os.path.abspath(directory)
        else:
            self.directory = os.path.dirname(self.path) if self.path else os.getcwd()
        self.name = name
        self.tree = tree
        self.text = text
        self.lines = text.split("\n")
        builder = ScopeBuilder(self)
        self.root = builder.build(tree)
        self.scope_by_node = builder.scope_by_node
        self.binding_by_target = builder.binding_by_target

    @property
    def is_namespace(self):
        return self.path is None

    @property
    def is_package(self):
        return self.is_namespace or os.path.basename(self.path) == "__init__.py"

    @property
    def location(self):
        """The file of the module, or the directory of a namespace package."""
        return self.path or self.directory

    def scope_of(self, node):
        return self.scope_by_node.get(id(node))

    def binding_of(self, node):
        """The binding created for a name node (or def/class/except node), if any."""
        return self.binding_by_target.get(id(node))


class Importer:
    """Resolves module names to values: project files first, then the standard library.

    Anything else (third-party packages, missing modules) is unresolvable.
    """

    def __init__(self, project_dir):
        self.project_dir = os.path.abspath(project_dir)
        self._contexts = {}
        self._namespaces = {}
        self._runtime = {}

    def register(self, context):
        if context.path:
            self._contexts[context.path] = context

    def module_name(self, location):
        """Dotted name of the module at `location` (file or directory), relative to the root."""
        try:
            relative = os.path.relpath(os.path.abspath(location), self.project_dir)
        except ValueError:  # another drive (Windows)
            relative = os.pardir
        if relative == os.curdir:
            return ""
        if relative == os.pardir or relative.startswith(os.pardir + os.sep):
            relative = os.path.basename(location)
        stem = os.path.splitext(relative)[0] if os.path.isfile(location) else relative
        parts = [p for p in stem.split(os.sep) if p]
        if parts and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def context_for_file(self, path, name=None):
        path = os.path.abspath(path)
        if path not in self._contexts:
            try:
                text = read_text(path)
            except SithError:
                return None
            if name is None:
                name = self.module_name(path)
            self._contexts[path] = ModuleContext(path, name, parse_tolerant(text), text)
        return self._contexts[path]

    def namespace_for(self, directory):
        directory = os.path.abspath(directory)
        if directory not in self._namespaces:
            self._namespaces[directory] = ModuleContext(
                None, self.module_name(directory), ast.Module(body=[], type_ignores=[]),
                directory=directory)
        return self._namespaces[directory]

    def _local(self, found):
        """A LocalModule for a `_locate` result."""
        if found is None:
            return None
        kind, location = found
        if kind == "namespace":
            return LocalModule(self.namespace_for(location))
        context = self.context_for_file(location)
        return LocalModule(context) if context else None

    # -- absolute and relative imports -------------------------------------------

    def import_absolute(self, dotted):
        """Resolve `import dotted` to a module value, or None."""
        if not dotted:
            return None
        parts = dotted.split(".")
        module = self.top_level(parts[0])
        if isinstance(module, RuntimeModule) and len(parts) > 1:
            return self._import_runtime(dotted)
        for part in parts[1:]:
            if module is None:
                return None
            module = self.submodule(module, part)
        return module

    def top_level(self, name):
        """The top-level module `name`: a project module or package, else stdlib."""
        found = _locate(self.project_dir, name, namespace=False)
        if found:
            return self._local(found)
        if name in STDLIB_NAMES:
            module = self._import_runtime(name)
            if module is not None:
                return module
        return self._local(_locate(self.project_dir, name, namespace=True))

    def submodule(self, module, name):
        """The submodule `name` of a package value, or None."""
        if isinstance(module, LocalModule):
            return self.local_submodule(module, name)
        if isinstance(module, RuntimeModule):
            return self.runtime_submodule(module, name)
        return None

    def import_relative(self, context, dotted, level):
        """Resolve `from <level dots><dotted> import ...` relative to `context`."""
        base = context.directory
        for _ in range(level - 1):
            base = os.path.dirname(base)
        if not self.within_project(base):
            return None
        module = self.package_at(base)
        for part in (dotted.split(".") if dotted else []):
            if module is None:
                return None
            module = self.local_submodule(module, part)
        return module

    def import_module(self, context, dotted, level=0):
        if level:
            return self.import_relative(context, dotted, level)
        return self.import_absolute(dotted)

    def within_project(self, directory):
        directory = os.path.abspath(directory)
        root = self.project_dir
        return directory == root or directory.startswith(root.rstrip(os.sep) + os.sep)

    def package_at(self, directory):
        """The package whose directory is `directory` (regular or namespace)."""
        init = _package_init(directory)
        if init:
            context = self.context_for_file(init)
            return LocalModule(context) if context else None
        if os.path.isdir(directory):
            return LocalModule(self.namespace_for(directory))
        return None

    def local_submodule(self, module_value, name):
        """A submodule `name` of a local package, if such a file or directory exists."""
        context = module_value.context
        if not context.is_package or not name:
            return None
        found = _locate(context.directory, name, namespace=False)
        return self._local(found or _locate(context.directory, name, namespace=True))

    def runtime_submodule(self, module_value, name):
        if not hasattr(module_value.obj, "__path__"):
            return None
        return self._import_runtime(f"{module_value.obj.__name__}.{name}")

    # -- listing modules (import completion) ------------------------------------

    def top_level_names(self):
        """Names of every importable top-level module."""
        return set(_module_names(self.project_dir)) | available_stdlib()

    def submodule_names(self, module):
        """Names of the submodules of a package value."""
        if isinstance(module, LocalModule):
            if not module.context.is_package:
                return set()
            return set(_module_names(module.context.directory))
        if isinstance(module, RuntimeModule):
            paths = getattr(module.obj, "__path__", None)
            if paths is None:
                return set()
            try:
                return {info.name for info in pkgutil.iter_modules(list(paths))}
            except Exception:
                return set()
        return set()

    def _import_runtime(self, dotted):
        if dotted.split(".")[0] not in STDLIB_NAMES:
            return None
        if dotted not in self._runtime:
            module = None
            try:
                with warnings.catch_warnings(), contextlib.redirect_stdout(io.StringIO()):
                    warnings.simplefilter("ignore")
                    module = importlib.import_module(dotted)
            except BaseException:  # importing arbitrary modules may fail in any way
                module = None
            self._runtime[dotted] = RuntimeModule(module) if module is not None else None
        return self._runtime[dotted]


_STDLIB_AVAILABLE = None


def available_stdlib():
    """Top-level standard library modules that exist in this runtime."""
    global _STDLIB_AVAILABLE
    if _STDLIB_AVAILABLE is None:
        names = set()
        for name in STDLIB_NAMES:
            if name == "__main__":
                continue
            try:
                if name in sys.modules or importlib.util.find_spec(name) is not None:
                    names.add(name)
            except Exception:
                continue
        _STDLIB_AVAILABLE = names
    return _STDLIB_AVAILABLE


def _locate(directory, name, namespace):
    """("file", path) or ("namespace", directory) for module `name` inside `directory`.

    Regular packages win over modules; namespace packages are only
    considered when `namespace` is true.
    """
    if not name or not os.path.isdir(directory):
        return None
    candidate = os.path.join(directory, name)
    if namespace:
        if os.path.isdir(candidate) and name.isidentifier():
            return "namespace", candidate
        return None
    init = _package_init(candidate)
    if init:
        return "file", init
    if os.path.isfile(candidate + ".py"):
        return "file", candidate + ".py"
    return None


def _module_names(directory):
    """Names of the modules and packages (including namespace packages) in `directory`."""
    try:
        entries = os.listdir(directory)
    except OSError:
        return []
    names = []
    for entry in entries:
        path = os.path.join(directory, entry)
        if entry.endswith(".py") and os.path.isfile(path):
            stem = entry[:-3]
            if stem.isidentifier() and stem != "__init__":
                names.append(stem)
        elif os.path.isdir(path) and entry.isidentifier() and entry != "__pycache__":
            names.append(entry)
    return names


def _package_init(directory):
    init = os.path.join(directory, "__init__.py")
    return init if os.path.isfile(init) else None

