    def binds(self, scope, name):
        if name in scope.bindings:
            return True
        return any(self._star_binding(star, name) is not None for star in scope.star_imports)

    def _star_binding(self, star, name):
        """A synthetic binding for `name` if the star import `star` provides it."""
        key = ("star", id(star), name)
        if key not in self._synthetic:
            if id(star) not in self._star_names:
                module = self.importer.import_module(star.scope.module, star.module, star.level)
                self._star_names[id(star)] = (
                    set(self.members.exported(module)) if module is not None else set())
            binding = None
            if name in self._star_names[id(star)]:
                binding = Binding(name, star.line, "importfrom", star.node, star.scope,
                                  extra=dict(module=star.module, level=star.level, attribute=name))
            self._synthetic[key] = binding
        return self._synthetic[key]

    def synthetic_binding(self, scope):
        """Factory for bindings that scope analysis does not record (see FlowAnalyzer)."""
        stars = {id(star.node): star for star in scope.star_imports}

        def create(kind, node, name):
            if kind == "star":
                star = stars.get(id(node))
                return self._star_binding(star, name) if star is not None else None
            key = (kind, id(node), name)
            if key not in self._synthetic:
                self._synthetic[key] = Binding(name, node.lineno, "augassign", node, scope,
                                               target=node.target)
            return self._synthetic[key]

        return create

    def flow_facts(self, scope, name, target):
        key = (id(scope), name, target)
        if key not in self._flow_cache:
            analyzer = FlowAnalyzer(scope, name, target, self.synthetic_binding(scope))
            self._flow_cache[key] = analyzer.run(initial_facts(scope, name))
        return self._flow_cache[key]

    def name_facts(self, name, scope, pos, strict=False):
        """Facts (bindings plus narrowings) for `name` used at `pos` in `scope`."""
        chain = self.resolution_chain(scope, pos, strict)
        return merge(self._facts_from(name, chain, 0, ()))

    def _facts_from(self, name, chain, index, narrowings):
        for position in range(index, len(chain)):
            current, target = chain[position]
            if not self.binds(current, name):
                if target is None or current.kind not in (FUNCTION, CLASS, MODULE):
                    continue
                # The name comes from further out, but conditions here may narrow it.
                facts = self.flow_facts(current, name, target) or [Fact(None)]
                result = []
                for fact in facts:
                    result += self._facts_from(name, chain, position + 1,
                                               fact.narrowings + narrowings)
                return result
            result = []
            for fact in self.flow_facts(current, name, target):
                combined = fact.narrowings + narrowings
                if fact.binding is None:
                    result += self._facts_from(name, chain, position + 1, combined)
                    continue
                prior = []
                for previous in fact.prior:
                    if previous.binding is None:
                        prior += self._facts_from(name, chain, position + 1, previous.narrowings)
                    else:
                        prior.append(previous)
                result.append(Fact(fact.binding, combined, prior))
            return result
        entry = self._builtins.get(name)
        if entry is None:
            return []
        if name not in self._builtin_bindings:
            self._builtin_bindings[name] = BuiltinBinding(name, entry)
        return [Fact(self._builtin_bindings[name], narrowings)]

    def scope_facts(self, scope, name):
        """Facts for `name` at the end of `scope` (bindings made in `scope` only)."""
        return [f for f in self.flow_facts(scope, name, None) if f.binding is not None]

    def scope_values(self, scope, name):
        return unique(v for f in self.scope_facts(scope, name) for v in self.fact_values(f))

    def name_values(self, name, scope, pos, strict=False):
        values = []
        for fact in self.name_facts(name, scope, pos, strict):
            values += self.fact_values(fact)
        return unique(values)

    def fact_values(self, fact):
        binding = fact.binding
        if binding is None:
            return []
        if isinstance(binding, BuiltinBinding):
            values = [binding.value()]
        elif binding.kind == "augassign":
            if fact.prior:
                node = binding.node
                lefts = unique(v for p in fact.prior for v in self.fact_values(p))
                values = self._operator_values(node.op, lefts, node.value, binding.scope, None, False)
                values = values or lefts
            else:
                values = self.infer_values(binding.node.value, binding.scope)
        else:
            values = self.binding_values(binding)
        values = unique(values)
        for narrowing in fact.narrowings:
            values = self.narrow(narrowing, values)
        return values

    # -- narrowing ---------------------------------------------------------------

    def narrow(self, narrowing, values):
        if narrowing.kind == "none":
            if narrowing.positive:
                return [v for v in values if is_none(v)] or [NONE]
            return [v for v in values if not is_none(v)]
        if narrowing.kind == "truthy":
            return [v for v in values if not is_none(v)]
        if narrowing.kind == "isinstance":
            classes = self.classinfo(narrowing.node, narrowing.scope)
            if not classes:
                return values
            if not narrowing.positive:
                return [v for v in values if not self.is_instance(v, classes)]
            result = []
            for value in values:
                if self.is_instance(value, classes):
                    result.append(value)
                    continue
                cls = self.class_of(value)
                if cls is not None:
                    result += [instance_of(c) for c in classes if self.is_subclass(c, cls)]
            return unique(result) or unique(instance_of(c) for c in classes)
        return values

    def classinfo(self, node, scope):
        elements = node.elts if isinstance(node, ast.Tuple) else [node]
        classes = []
        for element in elements:
            classes += [v for v in self.infer_values(element, scope)
                        if isinstance(v, (LocalClass, RuntimeClass))]
        return unique(classes)

    @staticmethod
    def class_of(value):
        if isinstance(value, LocalInstance):
            return value.cls
        if isinstance(value, RuntimeInstance):
            return RuntimeClass(value.cls)
        return None

    def is_instance(self, value, classes):
        cls = self.class_of(value)
        return cls is not None and any(self.is_subclass(cls, c) for c in classes)

    def is_subclass(self, cls, parent):
        if isinstance(parent, RuntimeClass) and parent.obj is object:
            return True
        if isinstance(cls, RuntimeClass):
            if not isinstance(parent, RuntimeClass):
                return False
            try:
                return issubclass(cls.obj, parent.obj)
            except TypeError:
                return False
        for current in self.members.mro(cls):
            if isinstance(parent, LocalClass) and current.scope is parent.scope:
                return True
            if isinstance(parent, RuntimeClass):
                for base in self.members.runtime_bases(current):
                    if self.is_subclass(base, parent):
                        return True
        return False

    # -- bindings ------------------------------------------------------------

    def _frame_signature(self):
        return tuple(frame.id for frame in self._frames)

    def infer_binding(self, binding):
        values = self.binding_values(binding)
        return values[0] if values else None

    def binding_values(self, binding):
        key = (id(binding), self._frame_signature())
        if key in self._binding_cache:
            return self._binding_cache[key]
        if key in self._active:
            return []
        self._active.add(key)
        try:
            values = unique(self._binding_values(binding))
        except RecursionError:
            values = []
        finally:
            self._active.discard(key)
        self._binding_cache[key] = values
        return values

    def _binding_values(self, binding):
        context = binding.scope.module
        kind = binding.kind
        extra = binding.extra
        if kind == "def":
            scope = context.scope_of(binding.node)
            return [LocalFunction(scope)] if scope else []
        if kind == "class":
            scope = context.scope_of(binding.node)
            return [LocalClass(scope)] if scope else []
        if kind == "import":
            return [self.importer.import_absolute(extra["module"])]
        if kind == "importfrom":
            return self.resolve_from_values(context, extra["module"], extra["level"],
                                            extra["attribute"])
        if kind == "assign":
            annotation = extra.get("annotation")
            if annotation is not None:
                values = self.annotation_values(annotation, binding.scope)
                if values:
                    return values
            if binding.value is not None:
                return self.infer_values(binding.value, binding.scope)
            return []
        if kind == "augassign":
            return self.infer_values(binding.node.value, binding.scope)
        if kind == "param":
            return self._param_values(binding)
        if kind == "except":
            exception = extra.get("exception")
            if exception is None:
                return []
            return [instance_of(c) for c in self.classinfo(exception, binding.scope)]
        if kind == "loop":
            if isinstance(binding.node.target, ast.Name):
                return self.iteration_values(binding.node.iter, binding.scope)
            return []
        if kind == "comprehension":
            generator = binding.node
            if isinstance(generator.target, ast.Name):
                outer = binding.scope
                if binding.scope.node.generators[0] is generator:
                    outer = binding.scope.parent
                return self.iteration_values(generator.iter, outer)
            return []
        if kind == "with":
            for item in binding.node.items:
                if isinstance(item.optional_vars, ast.Name) and item.optional_vars.id == binding.name:
                    return self.enter_values(item.context_expr, binding.scope)
            return []
        if kind == "pattern":
            pattern = binding.target
            if isinstance(pattern, ast.MatchAs) and isinstance(pattern.pattern, ast.MatchClass):
                return [instance_of(c) for c in self.classinfo(pattern.pattern.cls, binding.scope)]
            return []
        return []

    def in_frame(self, scope, args, bound, function):
        """Call `function()` with the parameters of `scope` bound to `args`/`bound`."""
        self._frames.append(_Frame(scope, args, bound))
        try:
            return function()
        finally:
            self._frames.pop()

    def resolve_from_values(self, context, module, level, attribute):
        """The values imported by `from <module> import <attribute>`."""
        base = self.importer.import_module(context, module, level)
        if base is not None:
            values = self.members.member_values(base, attribute)
            if values:
                return values
        if not level and module:
            return [self.importer.import_absolute(f"{module}.{attribute}")]
        return []

    def resolve_from(self, context, module, level, attribute):
        values = unique(self.resolve_from_values(context, module, level, attribute))
        return values[0] if values else None

    def annotation_values(self, annotation, scope, pos=None):
        """Instances described by a type annotation."""
        if annotation is None:
            return []
        if isinstance(annotation, ast.Constant):
            if annotation.value is None:
                return [NONE]
            if isinstance(annotation.value, str):
                try:
                    parsed = ast.parse(annotation.value.strip(), mode="eval").body
                except SyntaxError:
                    return []
                return self.annotation_values(parsed, scope, pos or _position(annotation))
            return []
        if isinstance(annotation, ast.BinOp) and isinstance(annotation.op, ast.BitOr):
            return unique(self.annotation_values(annotation.left, scope, pos)
                          + self.annotation_values(annotation.right, scope, pos))
        if isinstance(annotation, ast.Subscript):
            arguments = annotation.slice
            arguments = arguments.elts if isinstance(arguments, ast.Tuple) else [arguments]
            special = _typing_form(annotation.value, self.infer_values(annotation.value, scope, pos))
            if special == "Optional":
                return unique(self.annotation_values(arguments[0], scope, pos) + [NONE])
            if special == "Union":
                return unique(v for a in arguments for v in self.annotation_values(a, scope, pos))
            if special in ("ClassVar", "Final", "Annotated", "Required", "NotRequired"):
                return self.annotation_values(arguments[0], scope, pos)
            if special == "Type":
                return [v for v in self.infer_values(arguments[0], scope, pos)
                        if isinstance(v, (LocalClass, RuntimeClass))]
            annotation = annotation.value
        values = self.infer_values(annotation, scope, pos)
        return unique(instance_of(v) for v in values if isinstance(v, (LocalClass, RuntimeClass)))

    def _frame_for(self, scope):
        for frame in reversed(self._frames):
            if frame.scope is scope:
                return frame
        return None

    def _param_values(self, binding):
        node = binding.node
        arg = binding.extra["arg"]
        outer = binding.scope.parent
        if arg.annotation is not None:
            values = self.annotation_values(arg.annotation, outer)
            if values:
                if arg is node.args.vararg:
                    return [RuntimeInstance(tuple)]
                if arg is node.args.kwarg:
                    return [RuntimeInstance(dict)]
                return values
        positional = node.args.posonlyargs + node.args.args
        frame = self._frame_for(binding.scope)
        if frame is not None:
            if arg.arg in frame.args:
                return frame.args[arg.arg]
            if frame.bound is not None and positional and positional[0] is arg:
                return [frame.bound]
        if arg is node.args.vararg:
            return [RuntimeInstance(tuple)]
        if arg is node.args.kwarg:
            return [RuntimeInstance(dict)]
        default = _default_for(node.args, arg)
        if default is not None:
            return self.infer_values(default, outer)
        is_method = isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and outer.kind == CLASS
        if is_method and positional and positional[0] is arg:
            decorators = {_decorator_name(d) for d in node.decorator_list}
            if "staticmethod" in decorators:
                return []
            cls = LocalClass(outer)
            if "classmethod" in decorators or node.name in ("__new__", "__init_subclass__"):
                return [cls]
            return [LocalInstance(cls)]
        return []

    # -- expressions -----------------------------------------------------------

    def infer_values(self, node, scope, pos=None, strict=False):
        """All values expression `node` may evaluate to in `scope`.

        Names are resolved at their own position in the source, or at `pos`
        when given (for expressions parsed separately from the module).
        """
        if node is None or scope is None or self._depth > _MAX_DEPTH:
            return []
        self._depth += 1
        try:
            return unique(self._infer(node, scope, pos, strict))
        except RecursionError:
            return []
        finally:
            self._depth -= 1

    def _infer(self, node, scope, pos, strict):
        if isinstance(node, ast.Constant):
            return [RuntimeInstance(type(node.value))]
        literal = _LITERAL_TYPES.get(type(node))
        if literal is not None:
            return [RuntimeInstance(literal)]
        if isinstance(node, ast.Name):
            return self.name_values(node.id, scope, pos or _position(node), strict)
        if isinstance(node, ast.Attribute):
            values = []
            for base in self.infer_values(node.value, scope, pos, strict):
                values += self.members.member_values(base, node.attr)
            return values
        if isinstance(node, ast.Call):
            return self._call_values(node, scope, pos, strict)
        if isinstance(node, ast.Await):
            if isinstance(node.value, ast.Call):
                return self._call_values(node.value, scope, pos, strict, awaited=True)
            return []
        if isinstance(node, ast.Lambda):
            lambda_scope = scope.module.scope_of(node)
            return [LocalFunction(lambda_scope)] if lambda_scope else []
        if isinstance(node, ast.BinOp):
            return self._binop_values(node, scope, pos, strict)
        if isinstance(node, ast.UnaryOp):
            if isinstance(node.op, ast.Not):
                return [RuntimeInstance(bool)]
            return self.infer_values(node.operand, scope, pos, strict)
        if isinstance(node, ast.IfExp):
            return (self.infer_values(node.body, scope, pos, strict)
                    + self.infer_values(node.orelse, scope, pos, strict))
        if isinstance(node, ast.BoolOp):
            return [v for value in node.values for v in self.infer_values(value, scope, pos, strict)]
        if isinstance(node, ast.NamedExpr):
            return self.infer_values(node.value, scope, pos, strict)
        if isinstance(node, ast.Subscript):
            values = self.infer_values(node.value, scope, pos, strict)
            return [v for v in values if isinstance(v, RuntimeInstance) and v.cls in (str, bytes)]
        return []

    def _call_values(self, node, scope, pos, strict, awaited=False):
        values = []
        for function in self.infer_values(node.func, scope, pos, strict):
            values += self.call_result(function, node, scope, pos, strict, awaited)
        return values

    def call_result(self, function, call, scope, pos=None, strict=False, awaited=False):
        """Values returned by calling `function` with the arguments of `call`."""
        if isinstance(function, LocalClass):
            init = self.members.find_method(function, "__init__")
            args = None
            if init is not None:
                args = self.map_arguments(init.node, call, scope, pos, strict, offset=1)
            return [LocalInstance(function, args)]
        if isinstance(function, RuntimeClass):
            if function.obj is type and len(call.args) == 1:
                return [c for v in self.infer_values(call.args[0], scope, pos, strict)
                        for c in [self.class_of(v)] if c is not None]
            return [RuntimeInstance(function.obj)]
        if isinstance(function, LocalInstance):
            method = self.members.find_method(function.cls, "__call__")
            if method is None:
                return []
            function = LocalFunction(method.scope, function)
        if not isinstance(function, LocalFunction):
            return []
        node = function.node
        offset = 1 if function.bound is not None else 0
        args = self.map_arguments(node, call, scope, pos, strict, offset)
        if isinstance(node, ast.AsyncFunctionDef) and not awaited:
            return [RuntimeInstance(types.CoroutineType)]
        return self.return_values(function, args)

    def map_arguments(self, function_node, call, scope, pos, strict, offset=0):
        """{parameter name: values} for the arguments `call` passes to a function."""
        arguments = function_node.args
        positional = arguments.posonlyargs + arguments.args
        mapping = {}
        if call is None:
            return mapping
        for index, argument in enumerate(call.args):
            if isinstance(argument, ast.Starred):
                break
            if index + offset < len(positional):
                name = positional[index + offset].arg
                mapping[name] = self.infer_values(argument, scope, pos, strict)
        for keyword in call.keywords:
            if keyword.arg is not None:
                mapping[keyword.arg] = self.infer_values(keyword.value, scope, pos, strict)
        return {name: values for name, values in mapping.items() if values}

    def return_values(self, function, args=None):
        """The values returned by calling a locally defined function."""
        scope = function.scope
        node = scope.node
        key = ("return", id(node))
        if key in self._active:
            return []
        self._active.add(key)
        frame = _Frame(scope, args or {}, function.bound)
        self._frames.append(frame)
        try:
            if isinstance(node, ast.Lambda):
                return self.infer_values(node.body, scope)
            if node.returns is not None:
                values = self.annotation_values(node.returns, scope.parent)
                if values:
                    return values
            returns = []
            for child in walk_local(node.body):
                if isinstance(child, (ast.Yield, ast.YieldFrom)):
                    if isinstance(node, ast.AsyncFunctionDef):
                        return [RuntimeInstance(types.AsyncGeneratorType)]
                    return [RuntimeInstance(types.GeneratorType)]
                if isinstance(child, ast.Return):
                    returns.append(child)
            if not returns:
                return [NONE]
            values = []
            for statement in returns:
                if statement.value is None:
                    values.append(NONE)
                else:
                    values += self.infer_values(statement.value, scope)
            return unique(values)
        finally:
            self._frames.pop()
            self._active.discard(key)

    def iteration_values(self, iterable, scope):
        """Values produced by iterating over expression `iterable`."""
        if isinstance(iterable, (ast.List, ast.Tuple, ast.Set)):
            return unique(v for element in iterable.elts if not isinstance(element, ast.Starred)
                          for v in self.infer_values(element, scope))
        if isinstance(iterable, ast.Dict):
            return unique(v for key in iterable.keys if key is not None
                          for v in self.infer_values(key, scope))
        if isinstance(iterable, ast.Name):
            literals = []
            for fact in self.name_facts(iterable.id, scope, _position(iterable)):
                binding = fact.binding
                if (getattr(binding, "kind", None) == "assign" and binding.value is not None
                        and isinstance(binding.value, (ast.List, ast.Tuple, ast.Set, ast.Dict))):
                    literals += self.iteration_values(binding.value, binding.scope)
            if literals:
                return unique(literals)
        values = []
        for value in self.infer_values(iterable, scope):
            if isinstance(value, RuntimeInstance):
                if value.cls is str:
                    values.append(value)
                elif value.cls in (bytes, bytearray, range):
                    values.append(RuntimeInstance(int))
            elif isinstance(value, LocalInstance):
                method = self.members.find_method(value.cls, "__iter__")
                if method is not None:
                    for iterator in self.return_values(LocalFunction(method.scope, value)):
                        nxt = None
                        if isinstance(iterator, LocalInstance):
                            nxt = self.members.find_method(iterator.cls, "__next__")
                        if nxt is not None:
                            values += self.return_values(LocalFunction(nxt.scope, iterator))
        return unique(values)

    def enter_values(self, context_expr, scope):
        """The value bound by `with <context_expr> as name`."""
        values = []
        for value in self.infer_values(context_expr, scope):
            if isinstance(value, LocalInstance):
                method = self.members.find_method(value.cls, "__enter__")
                if method is not None:
                    values += self.return_values(LocalFunction(method.scope, value))
                    continue
            values.append(value)
        return unique(values)

    def _binop_values(self, node, scope, pos, strict):
        lefts = self.infer_values(node.left, scope, pos, strict)
        return self._operator_values(node.op, lefts, node.right, scope, pos, strict)

    def _operator_values(self, op, lefts, right_node, scope, pos, strict):
        """Values of `<left> <op> <right_node>` for each of the values `lefts`."""
        rights = None
        values = []
        for left in lefts:
            if isinstance(left, LocalInstance):
                method = self.members.find_method(left.cls, _OPERATOR_METHODS.get(type(op), ""))
                if method is not None:
                    values += self.return_values(LocalFunction(method.scope, left))
                continue
            if not isinstance(left, RuntimeInstance):
                continue
            if isinstance(op, ast.Mod) and left.cls in (str, bytes):
                values.append(left)
                continue
            if rights is None:
                rights = self.infer_values(right_node, scope, pos, strict)
            for right in rights:
                if not isinstance(right, RuntimeInstance):
                    continue
                if right.cls is left.cls:
                    if left.cls is bool and not isinstance(op, (ast.BitAnd, ast.BitOr, ast.BitXor)):
                        values.append(RuntimeInstance(int))
                    elif left.cls is int and isinstance(op, ast.Div):
                        values.append(RuntimeInstance(float))
                    else:
                        values.append(left)
                elif left.cls in _NUMERIC_TOWER and right.cls in _NUMERIC_TOWER:
                    wider = max(left.cls, right.cls, key=_NUMERIC_TOWER.index)
                    values.append(RuntimeInstance(max(wider, int, key=_NUMERIC_TOWER.index)))
                elif isinstance(op, ast.Mult) and {left.cls, right.cls} & {int, bool}:
                    sequence = right.cls if left.cls in (int, bool) else left.cls
                    values.append(RuntimeInstance(sequence))
        return values


def _position(node):
    return (node.lineno, node.col_offset)


def _typing_form(node, values):
    """The name of a typing special form (Optional, Union, ...) used as `node`."""
    for value in values:
        obj = getattr(value, "obj", None)
        if obj is not None and id(obj) in _TYPING_FORMS:
            return _TYPING_FORMS[id(obj)]
        if isinstance(value, RuntimeClass) and value.obj is type:
            return "Type"
    name = node.attr if isinstance(node, ast.Attribute) else getattr(node, "id", None)
    if not values and name in _TYPING_FORM_NAMES:
        return name
    return None


def _latest_binding(bindings, limit):
    """The binding in effect at line `limit` (any line when `limit` is None).

    A binding on the limit line itself (e.g. `x = x + 1`, or the statement
    being typed) only counts when there is no earlier one.
    """
    if limit is None:
        pool = bindings
    else:
        pool = [b for b in bindings if b.line < limit] or [b for b in bindings if b.line == limit]
    if not pool:
        return None
    return max(enumerate(pool), key=lambda pair: (pair[1].line, pair[0]))[1]


def _default_for(arguments, arg):
    positional = arguments.posonlyargs + arguments.args
    if arg in positional:
        offset = len(positional) - len(arguments.defaults)
        index = positional.index(arg)
        return arguments.defaults[index - offset] if index >= offset else None
    if arg in arguments.kwonlyargs:
        return arguments.kw_defaults[arguments.kwonlyargs.index(arg)]
    return None


def _decorator_name(node):
    if isinstance(node, ast.Call):
        node = node.func
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    return None

"""The `infer` and `goto` commands: what a name evaluates to, and where it is defined."""
import ast
import keyword
import os
import re
from dataclasses import dataclass, field

from . import context as cursor_context
from .definitions import DefinitionFactory, char_column, find_word, sorted_unique
from .errors import SithError
from .inference import Inferrer, RuntimeInstance
from .locate import find_scope
from .modules import Importer, ModuleContext
from .parsing import parse_tolerant, strip_comment
from .source import load_document
from .scopes import Binding
from .values import LocalClass, LocalFunction, LocalInstance, LocalModule, unique

INFER = "infer"
GOTO = "goto"


@dataclass
class Occurrence:
    """An identifier in the source and the role it plays there."""

    kind: str
    name: str
    start: int
    end: int
    node: ast.AST = None
    extra: dict = field(default_factory=dict)


def navigate(command, path, line, col, project=None, follow_imports=False):
    """Definitions for `command` ("infer" or "goto") at the cursor in `path`.

    With `follow_imports`, `goto` follows import statements to the
    definitions they import.
    """
    document = load_document(path)
    document.check_position(line, col)
    root = os.path.abspath(project or document.directory)
    importer = Importer(root)
    tree = parse_tolerant(document.text)
    context = ModuleContext(document.path, "__main__", tree, document.text)
    importer.register(context)
    inferrer = Inferrer(importer)
    navigator = Navigator(context, inferrer, DefinitionFactory(inferrer, root), line, col)
    occurrence = navigator.occurrence()
    if occurrence is None:
        raise SithError(f"no name at line {line}, column {col}")
    if command == GOTO:
        sources = navigator.goto(occurrence)
        if follow_imports:
            sources = navigator.follow_imports(sources)
    else:
        sources = navigator.infer(occurrence)
    factory = navigator.factory
    return sorted_unique(factory.from_source(source) for source in sources)


class Navigator:
    def __init__(self, context, inferrer, factory, line, col):
        self.context = context
        self.inferrer = inferrer
        self.factory = factory
        self.line = line
        self.col = col
        self.text = context.lines[line - 1] if line <= len(context.lines) else ""
        self.parents = {}
        for parent in ast.walk(context.tree):
            for child in ast.iter_child_nodes(parent):
                self.parents[id(child)] = parent

    # -- locating the identifier under the cursor ---------------------------------

    def occurrence(self):
        candidates = list(self._occurrences())
        inside = [o for o in candidates if o.start <= self.col < o.end]
        touching = [o for o in candidates if o.start <= self.col <= o.end]
        for group in (inside, touching):
            if group:
                return min(group, key=lambda o: o.end - o.start)
        return self._textual_occurrence()

    def _char(self, byte_col):
        return char_column(self.context, self.line, byte_col)

    def _occurrences(self):
        line = self.line
        for node in ast.walk(self.context.tree):
            if isinstance(node, ast.Name):
                if node.lineno == line == node.end_lineno:
                    yield Occurrence("name", node.id, self._char(node.col_offset),
                                     self._char(node.end_col_offset), node)
            elif isinstance(node, ast.Attribute):
                if node.end_lineno == line:
                    end = self._char(node.end_col_offset)
                    start = end - len(node.attr)
                    if self.text[start:end] == node.attr:
                        yield Occurrence("attr", node.attr, start, end, node)
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                if node.lineno == line:
                    match = re.compile(r"(?:async\s+)?(?:def|class)\s+").match(
                        self.text, self._char(node.col_offset))
                    if match and self.text.startswith(node.name, match.end()):
                        yield Occurrence("def", node.name, match.end(),
                                         match.end() + len(node.name), node)
            elif isinstance(node, ast.arg):
                if node.lineno == line:
                    start = self._char(node.col_offset)
                    yield Occurrence("param", node.arg, start, start + len(node.arg), node)
            elif isinstance(node, ast.alias):
                yield from self._alias_occurrences(node)
            elif isinstance(node, ast.ImportFrom):
                yield from self._import_from_module(node)
            elif isinstance(node, ast.keyword):
                if node.arg is not None and node.lineno == line:
                    start = self._char(node.col_offset)
                    yield Occurrence("kwarg", node.arg, start, start + len(node.arg), node,
                                     {"call": self.parents.get(id(node))})
            elif isinstance(node, ast.ExceptHandler):
                if node.name and node.lineno == line:
                    match = re.search(r"\bas\s+(" + re.escape(node.name) + r")\b", self.text)
                    if match:
                        yield Occurrence("bound", node.name, match.start(1), match.end(1), node)
            elif isinstance(node, (ast.MatchAs, ast.MatchStar, ast.MatchMapping)):
                name = getattr(node, "name", None) or getattr(node, "rest", None)
                if name and node.end_lineno == line:
                    end = self._char(node.end_col_offset)
                    start = self.text.rfind(name, 0, end)
                    if start >= 0:
                        yield Occurrence("bound", name, start, start + len(name), node)
            elif isinstance(node, (ast.Global, ast.Nonlocal)):
                if node.lineno == line:
                    position = self._char(node.col_offset)
                    for name in node.names:
                        found = find_word(self.text, name, position + 1)
                        if found is not None:
                            position = found
                            yield Occurrence("name", name, found, found + len(name), node)
            elif isinstance(node, ast.Constant):
                if node.value is None or isinstance(node.value, bool):
                    if node.lineno == line == node.end_lineno:
                        yield Occurrence("constant", repr(node.value), self._char(node.col_offset),
                                         self._char(node.end_col_offset), node)

    def _alias_occurrences(self, alias):
        if alias.lineno != self.line or alias.name == "*":
            return
        statement = self.parents.get(id(alias))
        start = self._char(alias.col_offset)
        if isinstance(statement, ast.Import):
            position = start
            parts = alias.name.split(".")
            for index, part in enumerate(parts):
                found = self.text.find(part, position)
                if found < 0:
                    break
                if index == 0 and not alias.asname:
                    yield Occurrence("bound", part, found, found + len(part), alias)
                else:
                    yield Occurrence("module", part, found, found + len(part), alias,
                                     {"module": ".".join(parts[:index + 1]), "level": 0})
                position = found + len(part)
        elif isinstance(statement, ast.ImportFrom):
            if alias.asname:
                yield Occurrence("imported", alias.name, start, start + len(alias.name), alias,
                                 {"statement": statement})
        else:
            return
        if isinstance(statement, ast.ImportFrom) and not alias.asname:
            yield Occurrence("bound", alias.name, start, start + len(alias.name), alias)
        if alias.asname:
            found = find_word(self.text, alias.asname, start + len(alias.name))
            if found is not None:
                yield Occurrence("bound", alias.asname, found, found + len(alias.asname), alias)

    def _import_from_module(self, node):
        if node.lineno != self.line:
            return
        match = re.compile(r"from\s+(\.*)\s*([\w.]*)").match(self.text, self._char(node.col_offset))
        if not match or not match.group(2):
            return
        position = match.start(2)
        parts = match.group(2).split(".")
        for index, part in enumerate(parts):
            yield Occurrence("module", part, position, position + len(part), node,
                             {"module": ".".join(parts[:index + 1]), "level": node.level})
            position += len(part) + 1

    def _textual_occurrence(self):
        """An identifier the parser lost (e.g. on a repaired line), if any."""
        text = self.text
        if self.col > len(strip_comment(text)) or self._in_string():
            return None
        start = end = self.col
        while start > 0 and cursor_context.is_identifier_char(text[start - 1]):
            start -= 1
        while end < len(text) and cursor_context.is_identifier_char(text[end]):
            end += 1
        word = text[start:end]
        if not word or word[0].isdigit() or keyword.iskeyword(word) or not word.isidentifier():
            return None
        receiver = None
        if text[:start].rstrip().endswith("."):
            before = "\n".join(self.context.lines[:self.line - 1] + [text[:start].rstrip()[:-1]])
            receiver = cursor_context.extract_receiver(before)
            if not receiver:
                return None
        return Occurrence("text", word, start, end, None, {"receiver": receiver})

    def _in_string(self):
        for node in ast.walk(self.context.tree):
            if isinstance(node, ast.Constant) and isinstance(node.value, (str, bytes)):
                start = (node.lineno, self._char(node.col_offset) if node.lineno == self.line else -1)
                end = (node.end_lineno, self._char(node.end_col_offset)
                       if node.end_lineno == self.line else 1 << 30)
                if start <= (self.line, self.col) < end:
                    return True
        return False

    # -- resolution ----------------------------------------------------------------

    def scope(self):
        return find_scope(self.context, self.line, self.col, self.text)

    def _byte_position(self, col):
        return (self.line, len(self.text[:col].encode("utf-8")))

    def goto(self, occurrence):
        """Bindings (or values, for runtime objects) defining the name at the cursor."""
        handler = getattr(self, "_goto_" + occurrence.kind)
        return handler(occurrence)

    def follow_imports(self, sources):
        """Replace import bindings among `sources` by the definitions they import.

        An import whose chain ends outside the project (stdlib, third-party or
        missing modules) is kept as it is: the import site is the fallback.
        """
        result = []
        for source in sources:
            followed = self._follow(source, set()) if _is_import(source) else None
            result += followed or [source]
        return result

    def _follow(self, binding, seen):
        """Definitions at the end of the import chain starting at `binding` ([] if unresolvable)."""
        if id(binding) in seen:
            return []
        seen.add(id(binding))
        importer = self.inferrer.importer
        if binding.kind == "import":
            module = importer.import_absolute(binding.extra.get("module", ""))
            return [module] if isinstance(module, LocalModule) else []
        context = binding.scope.module
        base = importer.import_module(context, binding.extra.get("module", ""),
                                      binding.extra.get("level", 0))
        if not isinstance(base, LocalModule):
            return []
        name = binding.extra.get("attribute", binding.name)
        root = base.context.root
        if not self.inferrer.binds(root, name):
            submodule = importer.local_submodule(base, name)
            return [submodule] if submodule is not None else []
        result = []
        for fact in self.inferrer.scope_facts(root, name):
            target = fact.binding
            if _is_import(target):
                result += self._follow(target, seen)
            else:
                result.append(target)
        return result

    def infer(self, occurrence):
        """Values the name at the cursor evaluates to."""
        handler = getattr(self, "_infer_" + occurrence.kind)
        return unique(handler(occurrence))

    # names

    def _name_facts(self, occurrence):
        node = occurrence.node
        position = (node.lineno, node.col_offset) if isinstance(node, ast.Name) else \
            self._byte_position(occurrence.start)
        return self.inferrer.name_facts(occurrence.name, self.scope(), position)

    def _store_binding(self, occurrence):
        node = occurrence.node
        if isinstance(node, ast.Name) and isinstance(node.ctx, ast.Store):
            binding = self.context.binding_of(node)
            if binding is not None:
                return binding
            parent = self.parents.get(id(node))
            if isinstance(parent, ast.AugAssign):
                scope = self.scope()
                return self.inferrer.synthetic_binding(scope)("aug", parent, node.id)
        return None

    def _goto_name(self, occurrence):
        binding = self._store_binding(occurrence)
        if binding is not None:
            return [binding]
        return [fact.binding for fact in self._name_facts(occurrence)]

    def _infer_name(self, occurrence):
        binding = self._store_binding(occurrence)
        if binding is not None and binding.kind != "augassign":
            return self.inferrer.binding_values(binding)
        values = []
        for fact in self._name_facts(occurrence):
            values += self.inferrer.fact_values(fact)
        return values

    # attributes

    def _instance_attribute(self, occurrence, bases):
        """The `self.attr = ...` binding at the cursor, with the instance it belongs to."""
        node = occurrence.node
        for base in bases:
            if isinstance(base, LocalInstance):
                for cls in self.inferrer.members.mro(base.cls):
                    for binding in self.inferrer.members.instance_attribute_bindings(cls).get(
                            occurrence.name, []):
                        if binding.target is node:
                            return binding, base
        return None, None

    def _goto_attr(self, occurrence):
        node = occurrence.node
        bases = self.inferrer.infer_values(node.value, self.scope())
        if isinstance(node.ctx, ast.Store):
            binding, _ = self._instance_attribute(occurrence, bases)
            if binding is not None:
                return [binding]
        sources = []
        for base in bases:
            sources += self.inferrer.members.member_definitions(base, occurrence.name)
        return sources

    def _infer_attr(self, occurrence):
        node = occurrence.node
        bases = self.inferrer.infer_values(node.value, self.scope())
        if isinstance(node.ctx, ast.Store):
            binding, instance = self._instance_attribute(occurrence, bases)
            if binding is not None:
                return self.inferrer.members.instance_attribute_values(binding, instance)
        values = []
        for base in bases:
            values += self.inferrer.members.member_values(base, occurrence.name)
        return values

    # definitions and other bound names

    def _bound_binding(self, occurrence):
        return self.context.binding_of(occurrence.node)

    def _goto_bound(self, occurrence):
        binding = self._bound_binding(occurrence)
        return [binding] if binding is not None else []

    def _infer_bound(self, occurrence):
        binding = self._bound_binding(occurrence)
        return self.inferrer.binding_values(binding) if binding is not None else []

    _goto_def = _goto_param = _goto_bound
    _infer_def = _infer_param = _infer_bound

    # modules named in import statements

    def _module_value(self, occurrence):
        module = self.inferrer.importer.import_module(
            self.context, occurrence.extra["module"], occurrence.extra["level"])
        return [module] if module is not None else []

    _goto_module = _infer_module = _module_value

    def _goto_imported(self, occurrence):
        statement = occurrence.extra["statement"]
        base = self.inferrer.importer.import_module(self.context, statement.module or "",
                                                    statement.level)
        if base is not None:
            found = self.inferrer.members.member_definitions(base, occurrence.name)
            if found:
                return found
        return self._infer_imported(occurrence)

    def _infer_imported(self, occurrence):
        statement = occurrence.extra["statement"]
        return self.inferrer.resolve_from_values(self.context, statement.module or "",
                                                 statement.level, occurrence.name)

    # keyword arguments

    def _keyword_parameters(self, occurrence):
        call = occurrence.extra.get("call")
        if not isinstance(call, ast.Call):
            return []
        bindings = []
        for function in self.inferrer.infer_values(call.func, self.scope()):
            if isinstance(function, LocalClass):
                init = self.inferrer.members.find_method(function, "__init__")
                if init is None:
                    # Generated `__init__` (dataclasses and the like): parameters are the fields.
                    for cls in self.inferrer.members.mro(function):
                        bindings += [b for b in cls.scope.bindings.get(occurrence.name, [])
                                     if b.extra.get("annotation") is not None]
                    continue
                function = init
            elif isinstance(function, LocalInstance):
                function = self.inferrer.members.find_method(function.cls, "__call__")
            if isinstance(function, LocalFunction):
                bindings += [b for b in function.scope.bindings.get(occurrence.name, [])
                             if b.kind == "param"]
        return bindings

    def _goto_kwarg(self, occurrence):
        return self._keyword_parameters(occurrence)

    def _infer_kwarg(self, occurrence):
        values = []
        for binding in self._keyword_parameters(occurrence):
            values += self.inferrer.binding_values(binding)
        return values

    # literals

    def _goto_constant(self, occurrence):
        return []

    def _infer_constant(self, occurrence):
        return [RuntimeInstance(type(occurrence.node.value))]

    # identifiers missing from the (repaired) syntax tree

    def _text_receiver_values(self, occurrence):
        try:
            expression = ast.parse(occurrence.extra["receiver"].strip(), mode="eval").body
        except (SyntaxError, ValueError):
            return []
        return self.inferrer.infer_values(expression, self.scope(),
                                          pos=self._byte_position(occurrence.start))

    def _goto_text(self, occurrence):
        if occurrence.extra.get("receiver"):
            sources = []
            for base in self._text_receiver_values(occurrence):
                sources += self.inferrer.members.member_definitions(base, occurrence.name)
            return sources
        return [fact.binding for fact in self._name_facts(occurrence)]

    def _infer_text(self, occurrence):
        if occurrence.extra.get("receiver"):
            values = []
            for base in self._text_receiver_values(occurrence):
                values += self.inferrer.members.member_values(base, occurrence.name)
            return values
        values = []
        for fact in self._name_facts(occurrence):
            values += self.inferrer.fact_values(fact)
        return values


def _is_import(source):
    return isinstance(source, Binding) and source.kind in ("import", "importfrom")

"""Definition records reported by `infer` and `goto`."""
import ast
import inspect
import os
import re
import sys
from dataclasses import asdict, dataclass

from .inference import BuiltinBinding
from .scopes import CLASS, FUNCTION, Binding
from .values import (
    LocalClass,
    LocalFunction,
    LocalInstance,
    LocalModule,
    RuntimeClass,
    RuntimeFunction,
    RuntimeInstance,
    RuntimeModule,
)

_DEFINITION_HEADER = re.compile(r"(?:async\s+)?(?:def|class)\s+")


@dataclass
class Definition:
    name: str
    type: str
    full_name: str
    module_path: str
    line: int
    column: int
    description: str
    docstring: str

    def to_dict(self):
        return asdict(self)

    @property
    def sort_key(self):
        return (self.module_path, self.line, self.column)


def sorted_unique(definitions):
    """Definitions without duplicates, sorted by (module_path, line, column)."""
    seen = set()
    result = []
    for definition in definitions:
        if definition is None:
            continue
        identity = tuple(definition.to_dict().items())
        if identity not in seen:
            seen.add(identity)
            result.append(definition)
    return sorted(result, key=lambda d: d.sort_key)


def normalize(text):
    return re.sub(r"\s+", " ", text).strip()


def char_column(context, line, byte_col):
    """Convert a UTF-8 byte offset on `line` to a character offset."""
    if not 1 <= line <= len(context.lines):
        return byte_col
    encoded = context.lines[line - 1].encode("utf-8")
    return len(encoded[:byte_col].decode("utf-8", errors="ignore"))


def posix_path(path):
    return path.replace(os.sep, "/") if os.sep != "/" else path


def find_word(text, word, start=0):
    """Column of the identifier `word` in `text` at or after `start`, or None."""
    match = re.compile(r"(?<![\w])" + re.escape(word) + r"(?![\w])").search(text, max(start, 0))
    return match.start() if match else None


class DefinitionFactory:
    """Builds Definition records for bindings and inferred values."""

    def __init__(self, inferrer, project_root):
        self.inferrer = inferrer
        self.project_root = os.path.abspath(project_root)

    # -- modules and paths -----------------------------------------------------

    def relative_path(self, path):
        """`path` relative to the project root (absolute outside it), with `/` separators."""
        if not path:
            return ""
        path = os.path.abspath(path)
        try:
            relative = os.path.relpath(path, self.project_root)
        except ValueError:
            return posix_path(path)
        if relative == os.pardir or relative.startswith(os.pardir + os.sep):
            return posix_path(path)
        return posix_path(relative)

    def module_name(self, context):
        """Dotted module name of a parsed file, relative to the project root."""
        if not context.path:
            return context.name
        relative = self.relative_path(context.path)
        if os.path.isabs(relative):
            if context.name and context.name != "__main__":
                return context.name
            relative = os.path.basename(relative)
        stem = os.path.splitext(relative)[0]
        parts = [p for p in stem.split("/") if p]
        if len(parts) > 1 and parts[-1] == "__init__":
            parts.pop()
        return ".".join(parts)

    def qualified_name(self, scope):
        """Dotted name of a scope: module, then enclosing classes and functions."""
        parts = []
        for current in scope.chain():
            if current.kind in (CLASS, FUNCTION):
                parts.append(current.node.name)
        parts.append(self.module_name(scope.module))
        return ".".join(reversed(parts))

    # -- source helpers --------------------------------------------------------

    @staticmethod
    def source(context, node):
        text = None
        try:
            text = ast.get_source_segment(context.text, node)
        except Exception:
            text = None
        if not text:
            try:
                text = ast.unparse(node)
            except Exception:
                text = ""
        return normalize(text)

    def parameters(self, context, arguments):
        """The parameter list of a function, formatted like its source."""

        def param(arg, default=None):
            text = arg.arg
            if arg.annotation is not None:
                text += ": " + self.source(context, arg.annotation)
            if default is not None:
                separator = " = " if arg.annotation is not None else "="
                text += separator + self.source(context, default)
            return text

        parts = []
        positional = arguments.posonlyargs + arguments.args
        defaults = [None] * (len(positional) - len(arguments.defaults)) + list(arguments.defaults)
        for index, arg in enumerate(positional):
            parts.append(param(arg, defaults[index]))
            if arguments.posonlyargs and index == len(arguments.posonlyargs) - 1:
                parts.append("/")
        if arguments.vararg is not None:
            parts.append("*" + param(arguments.vararg))
        elif arguments.kwonlyargs:
            parts.append("*")
        for arg, default in zip(arguments.kwonlyargs, arguments.kw_defaults):
            parts.append(param(arg, default))
        if arguments.kwarg is not None:
            parts.append("**" + param(arguments.kwarg))
        return ", ".join(parts)

    # -- bindings ----------------------------------------------------------------

    def from_source(self, source):
        """A Definition for a Binding, BuiltinBinding or Value."""
        if isinstance(source, BuiltinBinding):
            return self.from_value(source.value())
        if isinstance(source, Binding):
            return self.from_binding(source)
        return self.from_value(source)

    def from_binding(self, binding):
        context = binding.scope.module
        line, column = self.binding_position(binding)
        owner = binding.extra.get("owner")
        if owner is not None:
            full_name = f"{self.qualified_name(owner)}.{binding.name}"
        else:
            full_name = f"{self.qualified_name(binding.scope)}.{binding.name}"
        docstring = ""
        if binding.kind in ("def", "class"):
            docstring = ast.get_docstring(binding.node) or ""
        return Definition(
            name=binding.name,
            type=self.binding_type(binding),
            full_name=full_name,
            module_path=self.relative_path(context.path),
            line=line,
            column=column,
            description=self.binding_description(binding),
            docstring=docstring,
        )

    def binding_type(self, binding):
        kind = binding.kind
        if kind == "def":
            return "function"
        if kind == "class":
            return "class"
        if kind == "param":
            return "param"
        if kind == "import":
            return "module"
        if kind == "importfrom":
            values = self.inferrer.binding_values(binding)
            if values and values[0].kind:
                return values[0].kind
            return "module"
        return "statement"

    def binding_description(self, binding):
        context = binding.scope.module
        node = binding.node
        kind = binding.kind
        if kind == "def":
            return f"def {node.name}({self.parameters(context, node.args)})"
        if kind == "class":
            return f"class {node.name}"
        if kind == "param":
            return f"param {binding.name}"
        if kind in ("import", "importfrom"):
            return normalize(ast.unparse(node))
        if kind == "assign":
            if isinstance(node, (ast.Assign, ast.NamedExpr)) or (
                    isinstance(node, ast.AnnAssign) and node.value is not None):
                return self.source(context, node.value)
            return self.source(context, node)
        if kind in ("loop", "comprehension"):
            return f"for {self.source(context, node.target)} in {self.source(context, node.iter)}"
        if kind == "with":
            items = ", ".join(self.source(context, item) for item in node.items)
            return f"with {items}"
        if kind == "except":
            if node.type is None:
                return "except"
            return f"except {self.source(context, node.type)} as {binding.name}"
        if kind == "pattern":
            return f"case {self.source(context, node.pattern)}"
        return self.source(context, node)

    def binding_position(self, binding):
        """(1-based line, 0-based character column) of the bound identifier."""
        context = binding.scope.module
        target = binding.target
        node = binding.node
        lines = context.lines

        def text(line):
            return lines[line - 1] if 1 <= line <= len(lines) else ""

        if isinstance(target, (ast.Name, ast.arg)):
            return target.lineno, char_column(context, target.lineno, target.col_offset)
        if isinstance(target, ast.Attribute):
            end = char_column(context, target.end_lineno, target.end_col_offset)
            return target.end_lineno, end - len(target.attr)
        if isinstance(target, ast.alias):
            start = char_column(context, target.lineno, target.col_offset)
            if target.asname:
                found = find_word(text(target.lineno), target.asname, start + len(target.name))
                if found is not None:
                    return target.lineno, found
            return target.lineno, start
        if binding.kind in ("def", "class"):
            start = char_column(context, node.lineno, node.col_offset)
            match = _DEFINITION_HEADER.match(text(node.lineno), start)
            if match:
                return node.lineno, match.end()
            return node.lineno, start
        if binding.kind == "except":
            for line in range(node.lineno, (node.body[0].lineno if node.body else node.lineno) + 1):
                match = re.search(r"\bas\s+(" + re.escape(binding.name) + r")\b", text(line))
                if match:
                    return line, match.start(1)
        if isinstance(target, ast.pattern):
            for line in range(target.lineno, target.end_lineno + 1):
                start = char_column(context, line, target.col_offset) if line == target.lineno else 0
                found = find_word(text(line), binding.name, start)
                if found is not None:
                    return line, found
        if binding.kind == "importfrom" and isinstance(node, ast.ImportFrom):
            star = text(node.lineno).find("*")
            if star >= 0:
                return node.lineno, star
        found = find_word(text(binding.line), binding.name)
        return binding.line, found if found is not None else 0

    # -- values --------------------------------------------------------------------

    def from_value(self, value):
        if value is None:
            return None
        if isinstance(value, (LocalFunction, LocalClass)):
            return self._local_definition(value)
        if isinstance(value, LocalInstance):
            definition = self._local_definition(value.cls)
            if definition is None:
                return None
            definition.type = "instance"
            definition.description = f"instance of {value.cls.name}"
            return definition
        if isinstance(value, LocalModule):
            context = value.context
            name = self.module_name(context)
            return Definition(
                name=name.split(".")[-1],
                type="module",
                full_name=name,
                module_path=self.relative_path(context.location),
                line=1,
                column=0,
                description=f"module {name.split('.')[-1]}",
                docstring=ast.get_docstring(context.tree) or "",
            )
        if isinstance(value, RuntimeModule):
            return self._runtime_module(value.obj)
        if isinstance(value, RuntimeClass):
            return self._runtime_definition(value.obj, "class")
        if isinstance(value, RuntimeFunction):
            return self._runtime_definition(value.obj, "function")
        if isinstance(value, RuntimeInstance):
            return self._runtime_definition(value.cls, "instance")
        return None

    def _local_definition(self, value):
        node = value.scope.node
        context = value.scope.module
        if isinstance(node, ast.Lambda):
            parameters = self.parameters(context, node.args)
            return Definition(
                name="<lambda>",
                type="function",
                full_name=f"{self.qualified_name(value.scope.parent)}.<lambda>",
                module_path=self.relative_path(context.path),
                line=node.lineno,
                column=char_column(context, node.lineno, node.col_offset),
                description=f"def <lambda>({parameters})",
                docstring="",
            )
        binding = context.binding_of(node)
        if binding is None:
            return None
        return self.from_binding(binding)

    def _runtime_module(self, module):
        name = getattr(module, "__name__", "") or ""
        path = getattr(module, "__file__", None) or ""
        if path.endswith((".pyc", ".pyo")):
            path = path[:-1]
        if path and not path.endswith(".py"):
            path = ""
        return Definition(
            name=name.split(".")[-1],
            type="module",
            full_name=name,
            module_path=self.relative_path(path),
            line=1 if path else 0,
            column=0,
            description=f"module {name.split('.')[-1]}",
            docstring=_docstring(module),
        )

    def _runtime_definition(self, obj, kind):
        name = getattr(obj, "__name__", None) or type(obj).__name__
        qualname = getattr(obj, "__qualname__", None) or name
        module = getattr(obj, "__module__", None)
        if not isinstance(module, str):
            owner = getattr(obj, "__objclass__", None) or getattr(getattr(obj, "__self__", None), "__class__", None)
            module = getattr(owner, "__module__", None) if owner is not None else None
        module = module or "builtins"
        builtin = module == "builtins"
        path, line, column = ("", 0, 0) if builtin else _runtime_location(obj, name)
        if kind == "class":
            description = f"class {name}"
        elif kind == "instance":
            description = f"instance of {name}"
        else:
            description = f"def {name}({_runtime_parameters(obj)})"
        return Definition(
            name=name,
            type=kind,
            full_name=f"{module}.{qualname}",
            module_path=self.relative_path(path),
            line=line,
            column=column,
            description=description,
            docstring="" if builtin else _docstring(obj),
        )


def _docstring(obj):
    try:
        return inspect.getdoc(obj) or ""
    except Exception:
        return ""


def _runtime_parameters(obj):
    try:
        signature = inspect.signature(obj)
    except (TypeError, ValueError):
        return "..."
    text = str(signature.replace(return_annotation=inspect.Signature.empty))
    return text[1:-1]


def _runtime_location(obj, name):
    """(path, line, column) of a runtime class or function's source, if available."""
    path = ""
    module = sys.modules.get(getattr(obj, "__module__", None) or "")
    module_file = getattr(module, "__file__", None) or ""
    if module_file.endswith(".py"):
        path = module_file
    try:
        source_file = inspect.getsourcefile(obj)
        lines, start = inspect.getsourcelines(obj)
    except (TypeError, OSError):
        return path, 0, 0
    if not source_file:
        return path, 0, 0
    for offset, text in enumerate(lines):
        match = re.search(r"(?:def|class)\s+(" + re.escape(name) + r")\b", text)
        if match:
            return source_file, start + offset, match.start(1)
    return source_file, start, 0

"""Attribute resolution: the members exposed by each kind of value."""
import ast

from .entries import BindingEntry, ValueEntry
from .scopes import Binding, walk_local
from .values import (
    LocalClass,
    LocalFunction,
    LocalInstance,
    LocalModule,
    RuntimeClass,
    RuntimeFunction,
    RuntimeInstance,
    RuntimeModule,
    runtime_sample,
    unique,
    wrap_runtime,
)


def _sample_function():
    """Stand-in used to list the attributes of locally defined functions."""


def runtime_entries(obj):
    """Entries for `dir(obj)`, each resolving the attribute lazily."""
    try:
        names = dir(obj)
    except Exception:
        return {}
    return {name: ValueEntry(lambda name=name: wrap_runtime(getattr(obj, name))) for name in names}


def is_public(name):
    return not name.startswith("_")


class MemberResolver:
    def __init__(self, inferrer):
        self.inferrer = inferrer
        self._attribute_cache = {}

    def all(self, value):
        """Every attribute entry of `value`, keyed by name (submodules included)."""
        if isinstance(value, (LocalModule, RuntimeModule)):
            entries = dict(self.namespace(value))
            for name in self.inferrer.importer.submodule_names(value):
                if name not in entries:
                    entries[name] = ValueEntry(lambda name=name: self.member(value, name))
            return entries
        if isinstance(value, LocalClass):
            return self.class_members(value)
        if isinstance(value, LocalInstance):
            return self.instance_members(value.cls)
        if isinstance(value, (RuntimeClass, RuntimeFunction)):
            return runtime_entries(value.obj)
        if isinstance(value, RuntimeInstance):
            return runtime_entries(runtime_sample(value.cls))
        if isinstance(value, LocalFunction):
            return runtime_entries(_sample_function)
        return {}

    def namespace(self, value):
        """The names a module binds itself (no submodules that it does not import)."""
        if isinstance(value, LocalModule):
            return self.inferrer.scope_entries(value.context.root)
        if isinstance(value, RuntimeModule):
            return runtime_entries(value.obj)
        return self.all(value)

    def public(self, value):
        return {name: entry for name, entry in self.all(value).items() if is_public(name)}

    def dunder_all(self, value):
        """The names listed in a module's `__all__`, or None when it has none."""
        if isinstance(value, LocalModule):
            return static_all(value.context.tree)
        if isinstance(value, RuntimeModule):
            names = getattr(value.obj, "__all__", None)
            if isinstance(names, (list, tuple)) and all(isinstance(n, str) for n in names):
                return list(names)
        return None

    def exported(self, value, submodules=False):
        """Names a module exports: its `__all__`, else every name not starting with `_`.

        Without `submodules`, only names the module binds itself count (as
        for `from module import *`).
        """
        names = self.dunder_all(value)
        entries = self.all(value) if submodules else self.namespace(value)
        if names is None:
            return {name: entry for name, entry in entries.items() if is_public(name)}
        return {name: entries.get(name) or ValueEntry(lambda name=name: self.member(value, name))
                for name in names}

    def member(self, value, name):
        """The (first) value of attribute `name` of `value`, or None."""
        values = self.member_values(value, name)
        return values[0] if values else None

    def member_values(self, value, name):
        """Every value attribute `name` of `value` may have."""
        inferrer = self.inferrer
        importer = inferrer.importer
        if isinstance(value, LocalModule):
            root = value.context.root
            if inferrer.binds(root, name):
                return inferrer.scope_values(root, name)
            submodule = importer.local_submodule(value, name)
            return [submodule] if submodule is not None else []
        if isinstance(value, LocalClass):
            for cls in self.mro(value):
                if name in cls.scope.bindings:
                    values = []
                    for member in inferrer.scope_values(cls.scope, name):
                        values += self._bind_member(member, cls, value, None)
                    return unique(values)
            return self._runtime_base_member(value, name)
        if isinstance(value, LocalInstance):
            for cls in self.mro(value.cls):
                attributes = self.instance_attribute_bindings(cls).get(name, [])
                if not attributes and name not in cls.scope.bindings:
                    continue
                values = []
                for binding in attributes:
                    values += self.instance_attribute_values(binding, value)
                if name in cls.scope.bindings:
                    for member in inferrer.scope_values(cls.scope, name):
                        values += self._bind_member(member, cls, value.cls, value)
                return unique(values)
            return self._runtime_base_member(value.cls, name)
        entry = self.namespace(value).get(name)
        if entry is not None:
            member = entry.value()
            return [member] if member is not None else []
        if isinstance(value, RuntimeModule):
            submodule = importer.runtime_submodule(value, name)
            return [submodule] if submodule is not None else []
        return []

    def member_definitions(self, value, name):
        """Where attribute `name` of `value` is defined: bindings, or values for runtime objects."""
        inferrer = self.inferrer
        if isinstance(value, LocalModule):
            root = value.context.root
            if inferrer.binds(root, name):
                return [fact.binding for fact in inferrer.scope_facts(root, name)]
            return self.member_values(value, name)
        if isinstance(value, (LocalClass, LocalInstance)):
            cls_value = value if isinstance(value, LocalClass) else value.cls
            for cls in self.mro(cls_value):
                found = []
                if isinstance(value, LocalInstance):
                    found += self.instance_attribute_bindings(cls).get(name, [])
                if name in cls.scope.bindings:
                    found += [_property_getter(cls.scope, fact.binding)
                              for fact in inferrer.scope_facts(cls.scope, name)]
                if found:
                    return found
        return self.member_values(value, name)

    def instance_attribute_values(self, binding, instance):
        """Values of a `self.attr = ...` binding for a particular instance."""
        method = binding.scope
        if not instance.init_args or method.node.name != "__init__":
            return self.inferrer.binding_values(binding)
        return self.inferrer.in_frame(method, instance.init_args, instance,
                                      lambda: self.inferrer.binding_values(binding))

    def _bind_member(self, member, owner, cls, instance):
        """The value of a class-body member accessed on a class (`instance` None) or instance."""
        if not isinstance(member, LocalFunction) or member.bound is not None:
            return [member]
        node = member.node
        if not isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) or member.scope.parent is not owner.scope:
            return [member]
        decorators = {_decorator_name(d) for d in node.decorator_list}
        if "staticmethod" in decorators:
            return [member]
        if "classmethod" in decorators:
            return [LocalFunction(member.scope, cls)]
        if instance is None:
            return [member]
        if decorators & {"setter", "deleter"}:
            binding = owner.scope.module.binding_of(node)
            getter = _property_getter(owner.scope, binding) if binding is not None else None
            if getter is not None and getter is not binding:
                scope = owner.scope.module.scope_of(getter.node)
                if scope is not None:
                    member, decorators = LocalFunction(scope), {"property"}
        if decorators & {"property", "cached_property"}:
            return self.inferrer.return_values(LocalFunction(member.scope, instance))
        return [LocalFunction(member.scope, instance)]

    def find_method(self, cls, name):
        """The (unbound) local function `name` defined in the MRO of `cls`, or None."""
        for current in self.mro(cls):
            for binding in reversed(current.scope.bindings.get(name, [])):
                if binding.kind == "def":
                    scope = current.scope.module.scope_of(binding.node)
                    if scope is not None:
                        return LocalFunction(scope)
            if name in current.scope.bindings:
                return None
        return None

    def runtime_bases(self, cls):
        """The runtime (installed or builtin) classes among the direct bases of `cls`."""
        bases = []
        for base in cls.node.bases:
            bases += [v for v in self.inferrer.infer_values(base, cls.scope.parent)
                      if isinstance(v, RuntimeClass)]
        return bases

    def _runtime_base_member(self, cls, name):
        for current in self.mro(cls):
            for base in self.runtime_bases(current):
                if base.obj is not object and hasattr(base.obj, name):
                    member = wrap_runtime(getattr(base.obj, name))
                    return [member] if member is not None else []
        return []

    # -- classes -----------------------------------------------------------

    def mro(self, cls):
        """The class followed by its locally defined bases (depth first)."""
        order = []

        def visit(current):
            if any(current.scope is seen.scope for seen in order):
                return
            order.append(current)
            node = current.node
            for base in node.bases:
                for value in self.inferrer.infer_values(base, current.scope.parent):
                    if isinstance(value, LocalClass):
                        visit(value)

        visit(cls)
        return order

    def class_members(self, cls):
        members = {}
        for current in reversed(self.mro(cls)):
            members.update(self.inferrer.scope_entries(current.scope))
        return members

    def instance_members(self, cls):
        mro = self.mro(cls)
        members = {}
        for current in reversed(mro):
            members.update(self.inferrer.scope_entries(current.scope))
        for current in reversed(mro):
            for name, bindings in self.instance_attribute_bindings(current).items():
                members[name] = BindingEntry(bindings[0], self.inferrer)
        return members

    def instance_attribute_bindings(self, cls):
        """{name: bindings} for `self.<name> = ...` assignments in the methods of `cls`.

        Assignments in `__init__` come first.
        """
        key = id(cls.scope)
        if key in self._attribute_cache:
            return self._attribute_cache[key]
        entries = {}
        methods = []
        for bindings in cls.scope.bindings.values():
            methods += [b.node for b in bindings if b.kind == "def"]
        methods.sort(key=lambda node: (node.name != "__init__", node.lineno))
        for method in methods:
            decorators = {_decorator_name(d) for d in method.decorator_list}
            method_scope = cls.scope.module.scope_of(method)
            positional = method.args.posonlyargs + method.args.args
            if method_scope is None or not positional or decorators & {"staticmethod", "classmethod"}:
                continue
            self._collect_attributes(method, method_scope, positional[0].arg, cls, entries)
        self._attribute_cache[key] = entries
        return entries

    def _collect_attributes(self, method, method_scope, self_name, cls, entries):
        for node in walk_local(method.body):
            if isinstance(node, ast.Assign):
                for target in node.targets:
                    for attribute, target_node, value in _self_attributes(target, node.value, self_name):
                        binding = Binding(attribute, target_node.lineno, "assign", node, method_scope,
                                          value, {"owner": cls.scope}, target_node)
                        entries.setdefault(attribute, []).append(binding)
            elif isinstance(node, (ast.AnnAssign, ast.AugAssign)):
                for attribute, target_node, _ in _self_attributes(node.target, None, self_name):
                    if isinstance(node, ast.AugAssign) and attribute in entries:
                        continue
                    kind = "assign" if isinstance(node, ast.AnnAssign) else "augassign"
                    value = node.value if isinstance(node, ast.AnnAssign) else None
                    extra = {"owner": cls.scope}
                    if isinstance(node, ast.AnnAssign):
                        extra["annotation"] = node.annotation
                    binding = Binding(attribute, target_node.lineno, kind, node, method_scope, value,
                                      extra, target_node)
                    entries.setdefault(attribute, []).append(binding)


def static_all(tree):
    """The strings a module's top-level code puts in `__all__`, or None if it never assigns it."""
    state = {"names": None}

    def strings(node):
        if isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            return [e.value for e in node.elts
                    if isinstance(e, ast.Constant) and isinstance(e.value, str)]
        if isinstance(node, ast.BinOp) and isinstance(node.op, ast.Add):
            return strings(node.left) + strings(node.right)
        return []

    def visit(statements):
        for node in statements:
            if isinstance(node, (ast.Assign, ast.AnnAssign)):
                targets = node.targets if isinstance(node, ast.Assign) else [node.target]
                if any(isinstance(t, ast.Name) and t.id == "__all__" for t in targets):
                    state["names"] = strings(node.value) if node.value is not None else []
            elif isinstance(node, ast.AugAssign):
                if isinstance(node.target, ast.Name) and node.target.id == "__all__":
                    state["names"] = (state["names"] or []) + strings(node.value)
            elif isinstance(node, ast.Expr) and isinstance(node.value, ast.Call):
                call = node.value
                func = call.func
                if (isinstance(func, ast.Attribute) and isinstance(func.value, ast.Name)
                        and func.value.id == "__all__" and len(call.args) == 1
                        and state["names"] is not None):
                    argument = call.args[0]
                    if func.attr == "extend":
                        state["names"] = state["names"] + strings(argument)
                    elif func.attr in ("append", "remove") and isinstance(argument, ast.Constant) \
                            and isinstance(argument.value, str):
                        if func.attr == "append":
                            state["names"] = state["names"] + [argument.value]
                        elif argument.value in state["names"]:
                            state["names"] = [n for n in state["names"] if n != argument.value]
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef, ast.ClassDef)):
                continue
            else:
                for field in ("body", "orelse", "finalbody"):
                    visit(getattr(node, field, None) or [])
                for handler in getattr(node, "handlers", None) or []:
                    visit(handler.body)

    visit(tree.body)
    names = state["names"]
    if names is None:
        return None
    return list(dict.fromkeys(names))


def _property_getter(class_scope, binding):
    """For the `@<name>.setter`/`.deleter` def `binding`, the `@property` getter; else `binding`."""
    if binding.kind != "def":
        return binding
    if not {_decorator_name(d) for d in binding.node.decorator_list} & {"setter", "deleter"}:
        return binding
    for candidate in class_scope.bindings.get(binding.name, []):
        if candidate.kind == "def" and "property" in {
                _decorator_name(d) for d in candidate.node.decorator_list}:
            return candidate
    return binding


def _decorator_name(node):
    if isinstance(node, ast.Call):
        node = node.func
    if isinstance(node, ast.Attribute):
        return node.attr
    if isinstance(node, ast.Name):
        return node.id
    return None


def _self_attributes(target, value, self_name):
    """Yield (attribute name, target node, value) for `self.attr` targets."""
    if isinstance(target, ast.Attribute):
        if isinstance(target.value, ast.Name) and target.value.id == self_name:
            yield target.attr, target, value
    elif isinstance(target, (ast.Tuple, ast.List)):
        values = None
        if isinstance(value, (ast.Tuple, ast.List)) and len(value.elts) == len(target.elts):
            values = value.elts
        for index, element in enumerate(target.elts):
            yield from _self_attributes(element, values[index] if values else None, self_name)
    elif isinstance(target, ast.Starred):
        yield from _self_attributes(target.value, None, self_name)

