cd /workspace; for f in sithlib/signatures.py sithlib/references.py sithlib/listing.py sithlib/stubs.py sithlib/project.py sithlib/cli.py sithlib/inference.py; do python3 - "$f" <<'EOF'
import ast, sys
src = open(sys.argv[1]).read(); tree = ast.parse(src)
names = set()
for n in ast.walk(tree):
    if isinstance(n, (ast.Import, ast.ImportFrom)):
        for a in n.names: names.add((a.asname or a.name).split(".")[0])
used = {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.value.id for n in ast.walk(tree) if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name)}
print(sys.argv[1], sorted(names - used))
EOF
done

